(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c68"]=[{"id":"00000900","register_sub_id":"101","register_pk":"101890","name":"知新館表門","kana":"ちしんかんおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県津山市南新座26","lat":35.05827572,"lng":133.99816551,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造腕木門，瓦葺，高さ2.8m，幅3.8m","structure_material":"木造腕木門","registered":"1998.10.09(平成10.10.09)","register_no":"33 － 0024","desc":"主屋の正面に開かれた三間一戸の門。左右に塀が取り付く。腕木を出して屋根を支える簡略な形式になり比較的に小規模だが，道路よりわずかに下げて建ち正面に石橋風の構えをつくるなど意匠上の配慮がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000900"},{"id":"00000897","register_sub_id":"101","register_pk":"101887","name":"知新館主屋","kana":"ちしんかんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県津山市南新座26","lat":35.05812499,"lng":133.9981265,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積229㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"33 － 0021","desc":"津山城跡の西方南寄りの旧武家屋敷街に位置する。平沼騏一郎に郷土や法曹の人々等が，古希の祝いとしてその生家を再現して贈ったもので，主屋は，棟を段違いにつくり座敷，台所，玄関を備えた武家住宅らしいつくりになる。現在市民の文化活動の場として活用。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000897"},{"id":"00000898","register_sub_id":"101","register_pk":"101888","name":"知新館土蔵","kana":"ちしんかんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県津山市南新座26","lat":35.05821491,"lng":133.99824865,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積45㎡","structure_material":"土蔵造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"33 － 0022","desc":"主屋の北西にあり，道路に面して建つ比較的にせいの高い２階建，桟瓦葺の土蔵。１階の腰から下の部分で外壁の仕様をかえ，主屋や道路側の塀と意匠をあわせている。武家の屋敷構えをつくる主要な構成要素として貴重な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000898"},{"id":"00000899","register_sub_id":"101","register_pk":"132569","name":"知新館塀","kana":"ちしんかんへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県津山市南新座26","lat":35.05828813,"lng":133.99804847,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"土塀，瓦葺，延長26.3m","structure_material":"土塀","registered":"1998.10.09(平成10.10.09)","register_no":"33 － 0023","desc":"主屋の北にあり，道路に面してめぐらされた屋根塀。腰壁に板を貼り，上部の壁を漆喰で塗り込める。市内にはいくつか武家屋敷が残る地域があるが，南新座ではその数が減少してきており，地域の中心部にあり屋敷構えを伝える事例として貴重な存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000899"},{"id":"00001082","register_sub_id":"101","register_pk":"102072","name":"天籟庵","kana":"てんらいあん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県加賀郡吉備中央町大字吉川3932-3","lat":34.81969366,"lng":133.75136597,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積17㎡","structure_material":"木造平屋建","registered":"1999.02.17(平成11.02.17)","register_no":"33 － 0029","desc":"地元出身の庭園研究家重森三玲の処女作品とされる。もと重森邸に建てられた茶室で，昭和４４年現在地に重森三玲自身の手により移築された。４畳半の茶席と３畳大の水屋より成る。茶席の真行草三つの床構えは特異。茶席天井の意匠も秀逸である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001082"},{"id":"00014411","register_sub_id":"101","register_pk":"511400","name":"戸田家住宅主屋","kana":"とだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県新見市上熊谷字乙原3563","lat":35.02156111,"lng":133.51128611,"geo_status":"db","era":"天明6年(1786)頃／大正5年頃・昭和35年・同43年改修","year":1786,"year_source":"db","year_min":1786,"year_max":1786,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積243㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"33 - 0350","desc":"中世山城の麓にあり、長大な石垣を構えた旧家の主屋。つし二階建、入母屋造平入桟瓦葺、二階壁は海鼠壁に虫籠窓を開ける。内部は西を土間、東に六室を配し、南東隅を主座敷として庭に臨む。式台を備え、木柄の太い梁組等に庄屋らしさを留めた豪壮な主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014411"},{"id":"00012637","register_sub_id":"101","register_pk":"367931","name":"仲﨑家住宅主屋","kana":"なかざきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県瀬戸内市長船町福岡字東小路689","lat":34.702591,"lng":134.092224,"geo_status":"geocoded","era":"大正6年頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積190㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"33 － 0302","desc":"備前福岡の地主宅主屋で、敷地北寄りに西面して建つ。総二階建、起りのある入母屋造の四周に下屋を廻す。一階は前後二列各三室を配し、廊下や壁で表裏を明確に画する。二階には座敷や洋室を配する。内外に優れた造作を施し、集落景観の核となる大規模住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012637"},{"id":"00014938","register_sub_id":"101","register_pk":"519198","name":"長鋪家住宅内蔵","kana":"ながしきけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県笠岡市神島字汁方3042","lat":34.46920278,"lng":133.50848611,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積29㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"33 - 0359","desc":"主屋南に位置する土蔵。二階建切妻造平入本瓦葺の東西棟。北を戸口として庇を付し、窓を二箇所開け、外壁は漆喰塗仕上で出隅と二階腰を海鼠壁。１階は一室の土間で東辺に穀倉を区画し、二階は一室の板敷で家財道具を収納する。重厚な外観が屋敷景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014938"},{"id":"00014939","register_sub_id":"101","register_pk":"519199","name":"長鋪家住宅内門","kana":"ながしきけじゅうたくうちもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県笠岡市神島字汁方3042","lat":34.46926944,"lng":133.50845,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、間口1.3m、袖塀付","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"33 - 0360","desc":"主屋座敷の南西に位置し、庭を区画する門。東面する一間一戸の薬医門で、切妻造桟瓦葺の南北棟。控柱は足固貫、腰貫、頭貫で固め、大斗肘木で受けた男梁上に笈形付大瓶束で棟木を支持。軒は一軒繁垂木、大棟は組棟とする。丁寧なつくりの門で旧家の格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014939"},{"id":"00014937","register_sub_id":"101","register_pk":"519197","name":"長鋪家住宅主屋","kana":"ながしきけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県笠岡市神島字汁方3042","lat":34.46936389,"lng":133.50846389,"geo_status":"db","era":"江戸末期／大正前期・昭和49年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積65㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"33 - 0358","desc":"神島北東の高台に位置する旧家の主屋。平屋建の東西棟で西寄りは入母屋造本瓦葺で三方に下屋を付して錣葺風とし、東寄りは切妻造桟瓦葺とする。内部は東西に三室を配し、東端室を床構え付き座敷とする。南庭に面して軒を二軒とするなど上質なつくりの主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014937"},{"id":"00003707","register_sub_id":"101","register_pk":"104697","name":"西江家住宅隠居座敷","kana":"にしえけじゅうたくいんきょざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県高梁市坂本1604","lat":34.86917387,"lng":133.44933206,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積35㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"33 － 0078","desc":"主屋背後の奥まったところに位置し，主屋浴室の南西に接続する。２階建，寄棟造，桟瓦葺で，東西面とも大きく開口し開放的なつくりとなる。１階は茶室風の小部屋に区画し，２階に１０畳間２室を配する。凝った装飾はないが清明な数寄屋風意匠でまとめた座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003707"},{"id":"00003714","register_sub_id":"101","register_pk":"104704","name":"西江家住宅旧馬小屋及び男部屋","kana":"にしえけじゅうたくきゅううまごやおよびおとこべや","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県高梁市成羽町坂本1604","lat":34.86876935,"lng":133.44934448,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺、建築面積198㎡","structure_material":"土蔵造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"33 － 0085","desc":"門の南に東西に長く配され，西端は主屋東面南端部に接続する。桁行東方約３分の２に馬房を１列に並べ，この西方には１部屋と土間を取り，つし２階を設ける。屋根は桟瓦葺で，東正面を入母屋造とする。屋敷正面の構え及び主屋前庭の景観形成上欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003714"},{"id":"00003710","register_sub_id":"101","register_pk":"104700","name":"西江家住宅穀蔵（西江家資料館）","kana":"にしえけじゅうたくこくぐら（にしえけしりょうかん）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県高梁市坂本1604","lat":34.8689769,"lng":133.44957603,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積79㎡","structure_material":"土蔵造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"33 － 0081","desc":"敷地北東隅の懸崖に築いた石垣上に建つ。切妻造，桟瓦葺の２階建土蔵で，南半を米，北半を麦の貯蔵庫とする。軒，螻羽を塗込め，胴部に水切りの小庇を回し，腰，隅，水切り上，破風などを海鼠瓦張とするなど，丁寧なつくりであるとともに景観上も目立つ存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003710"},{"id":"00003706","register_sub_id":"101","register_pk":"104696","name":"西江家住宅主屋","kana":"にしえけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県高梁市坂本1604","lat":34.86899629,"lng":133.44933929,"geo_status":"db","era":"江戸後期／明治27頃改造","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積320㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"33 － 0077","desc":"間口２７ｍに及ぶ大型の建物で，東面して建つ。２階建主体部を中心に，北西に廊下を介して浴室を付属する。正面に式台玄関と応接室を突出するとともに，赤褐色の石州瓦，漆喰塗，海鼠壁の対比により変化に富む華やかな外観を呈し，屋敷構えの中核を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003706"},{"id":"00003711","register_sub_id":"101","register_pk":"104701","name":"西江家住宅書庫","kana":"にしえけじゅうたくしょこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県高梁市坂本1604","lat":34.86906887,"lng":133.44955145,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺、建築面積23㎡","structure_material":"土蔵造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"33 － 0082","desc":"主屋の北方，穀蔵西に露地をはさんで建つ。切妻造，桟瓦葺，平屋建の土蔵で，東妻面に出入口を開ける。外壁各面には水切り小庇を妻，平で高さを変えて付け，腰，隅，水切り上を海鼠瓦張とする。小規模だが入念な仕事になり，屋敷構えの構成上欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003711"},{"id":"00003712","register_sub_id":"101","register_pk":"104702","name":"西江家住宅道具蔵","kana":"にしえけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県高梁市坂本1604","lat":34.86906987,"lng":133.4491551,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"33 － 0083","desc":"主屋背後，裏庭の奥に建つ家財道具を納める蔵。２階建，切妻造，桟瓦葺で，１階東面２箇所に出入口を開ける。胴部各面に水切り小庇を妻，平で高さを変えて付け，腰，隅，水切り上，破風を海鼠瓦張とする。大型で上質なつくりの土蔵で屋敷西辺の構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003712"},{"id":"00003713","register_sub_id":"101","register_pk":"104703","name":"西江家住宅味噌蔵","kana":"にしえけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県高梁市坂本1604","lat":34.86902123,"lng":133.44906261,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積15㎡","structure_material":"土蔵造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"33 － 0084","desc":"主屋土間の背後，道具蔵南に隣接して建つ。２階建，切妻造，桟瓦葺の土蔵で，１階東妻面に腕木を出して庇を設け，戸口を開ける。腰，隅，庇上などに海鼠瓦張を施し，東妻拝み部分に家紋の揚羽蝶紋を付す。小規模ながら道具蔵と並んで屋敷西方の構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003713"},{"id":"00003708","register_sub_id":"101","register_pk":"104698","name":"西江家住宅門","kana":"にしえけじゅうたくもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県高梁市坂本1604","lat":34.86877016,"lng":133.44950132,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、瓦葺、建築面積20㎡","structure_material":"木造","registered":"2003.12.01(平成15.12.01)","register_no":"33 － 0079","desc":"敷地東端の正面出入口に開く入母屋造，桟瓦葺の脇戸付櫓門。表裏に庇を付し，２階は両面とも中央に格子窓を開けるが，表側は細かい組子の出格子窓とする。住宅には珍しい重厚な形式をもち棟両端に鯱を置くなど派手なつくりで，豪壮な屋敷構えの正面を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003708"},{"id":"00003709","register_sub_id":"101","register_pk":"104699","name":"西江家住宅門座敷","kana":"にしえけじゅうたくもんざしき","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県高梁市坂本1604","lat":34.86882326,"lng":133.44952142,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"33 － 0080","desc":"屋敷東面，門の北に接続し，急峻な崖に築いた石垣上に建つ。入母屋造，桟瓦葺の建物で内部に座敷２室を配し，平屋建だが高く建ち上げた床下を物置に利用する。東及び北面の窓に高欄を付け，床下を海鼠壁とするなど外観の意匠を凝らし屋敷正面の構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003709"},{"id":"00001642","register_sub_id":"101","register_pk":"102632","name":"野﨑家別邸たい暇堂大門","kana":"のざきけべっていたいかどうおおもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島味野1-8-34","lat":34.47137321,"lng":133.80426397,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"石造、間口4.3m","structure_material":"石造","registered":"2000.04.28(平成12.04.28)","register_no":"33 － 0044","desc":"暇堂の正門にあたる門で，野﨑家本宅御成門から小田川へ降りる街路に向けて門を開く。門柱は，高さ３．６ｍの角柱で，花崗石の一本石からつくりだし，各面は叩き仕上げとし，頭部を大斗状に刳った丁寧なつくりとする。門扉は木製で洋風の仕立てになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001642"},{"id":"00001643","register_sub_id":"101","register_pk":"102633","name":"野﨑家別邸たい暇堂胸像台座","kana":"のざきけべっていたいかどうきょうぞうだいざ","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島味野1-8-34","lat":34.47115855,"lng":133.80480741,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"石造、高さ2m","structure_material":"石造","registered":"2000.04.28(平成12.04.28)","register_no":"33 － 0045","desc":"主屋大広間の東方，東塀寄りに建立された野﨑武吉郎胸像の台座。総花崗石造で，２段の基壇の上に立方体状の礎石を置き，緩くテーパーをつけた角柱状の台座石を載せる。高さは約２ｍ。野﨑家貸費生らによる建立と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001643"},{"id":"00001635","register_sub_id":"101","register_pk":"102625","name":"野﨑家別邸たい暇堂居宅","kana":"のざきけべっていたいかどうきょたく","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島味野1-8-34","lat":34.47135914,"lng":133.80419496,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"33 － 0037","desc":"主屋炊事場の北端部東面から東方の大門へむけてＬ字型に建てられた木造，平屋建，桟瓦葺，寄棟造建屋。屋敷地を維持管理する使用人の住宅とされる。式台玄関に通じる大門の右手に位置し，大門左手の車寄（人力車置場）と車夫詰所とともに前庭を囲う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001635"},{"id":"00001632","register_sub_id":"101","register_pk":"102622","name":"野﨑家別邸たい暇堂蔵","kana":"のざきけべっていたいかどうくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島味野1-8-34","lat":34.47112369,"lng":133.80408176,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造2階建、瓦葺、建築面積186㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"33 － 0034","desc":"主屋配膳室の西方に位置する南北棟，切妻造，平入の２階建，海鼠壁土蔵で，宴会時の備品類を収納しておく道具蔵とされる。南方の桁行３間半分は梁行が北方部より半間分広く，その階下を１０畳間の居室とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001632"},{"id":"00001637","register_sub_id":"101","register_pk":"102627","name":"野﨑家別邸たい暇堂車寄","kana":"のざきけべっていたいかどうくるまよせ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島味野1-8-34","lat":34.4713709,"lng":133.80434962,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"33 － 0039","desc":"主屋式台玄関の前庭の東方に位置し，大門を入った左手に建つ。桁行３間，奥行２間規模の人力車置場で，西面を吹放ちとし，人力車４台分を収納する。屋敷の利用状況を物語る施設であるとともに，時代と地方の交通事情の一端を窺い知る上で貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001637"},{"id":"00001638","register_sub_id":"101","register_pk":"102628","name":"野﨑家別邸たい暇堂車夫詰所","kana":"のざきけべっていたいかどうしゃふつめしょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島味野1-8-34","lat":34.47139321,"lng":133.80432338,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"33 － 0040","desc":"車寄（人力車置場）の北方に接続して建つ木造，平屋建，瓦葺，東西棟，寄棟造の人力車夫詰所。桁行２間，梁行１間半の簡素な建屋であるが，軒裏の垂木を扇状に配するなど相応の意匠的配慮がとられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001638"},{"id":"00001631","register_sub_id":"101","register_pk":"102621","name":"野﨑家別邸たい暇堂主屋","kana":"のざきけべっていたいかどうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島味野1-8-34","lat":34.47113342,"lng":133.804405,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造平屋建一部2階建、瓦葺、建築面積856㎡","structure_material":"木造平屋建一部2階建","registered":"2000.04.28(平成12.04.28)","register_no":"33 － 0033","desc":"児島の塩田王が本宅（県指定史跡）近くの小田川沿いに建設した迎賓館的施設。主屋は，入母屋造の式台玄関の奥南方に寄棟造の１００畳敷広間を張り出し，右手西方に配膳室・炊事場等，左手東方に風呂・便所を配した大規模にして複雑な建築構成をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001631"},{"id":"00001636","register_sub_id":"101","register_pk":"102626","name":"野﨑家別邸たい暇堂清恬","kana":"のざきけべっていたいかどうせいてん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島味野1-8-34","lat":34.470951,"lng":133.80491766,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、よし葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"33 － 0038","desc":"主屋大広間の南方に拡がる庭園の東方，小田川に沿った東塀寄りの一画に葭葺の瀟洒な姿を見せる。有亭と同様に野﨑武吉郎の還暦記念に建てられた茶室棟で，中板付き３畳台目の茶室を有し，東門からのアプローチを考慮した露地構成をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001636"},{"id":"00001639","register_sub_id":"101","register_pk":"102629","name":"野﨑家別邸たい暇堂中門","kana":"のざきけべっていたいかどうちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島味野1-8-34","lat":34.47130586,"lng":133.80439317,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造、檜皮葺、間口1.7m","structure_material":"木造","registered":"2000.04.28(平成12.04.28)","register_no":"33 － 0041","desc":"主屋風呂場・便所棟と車寄（人力車置場）とを繋ぐ竹詰塀の中央に開けられた門で，主屋式台玄関前の前庭を東方で限る。前庭から主屋便所の脇を通って南庭に向かう園路の入口にあたる門で，棟を瓦で押さえた檜皮葺の端正な姿形をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001639"},{"id":"00001640","register_sub_id":"101","register_pk":"102630","name":"野﨑家別邸たい暇堂東塀","kana":"のざきけべっていたいかどうひがしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島味野1-8-34","lat":34.47130002,"lng":133.80475859,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"土塀、瓦葺、延長76m、木造門附属","structure_material":"土塀","registered":"2000.04.28(平成12.04.28)","register_no":"33 － 0042","desc":"車寄（人力車置場）南端から発し，小田川沿いの敷地東辺に連なる土塀で，東辺南寄りに本瓦葺，一間薬医門形式の東門を開く。土塀は，棟高約２．４ｍで，幅８０ｃｍの花崗石の基礎に建ち，腰を洗出し仕上げにし，桟瓦を載せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001640"},{"id":"00001633","register_sub_id":"101","register_pk":"102623","name":"野﨑家別邸たい暇堂有藇亭","kana":"のざきけべっていたいかどうゆうよてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島味野1-8-34","lat":34.47100583,"lng":133.80422762,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、よし葺一部瓦・銅板葺、建築面積82㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"33 － 0035","desc":"主屋配膳室南方の茶室（聴鶯軒）から西南方に栗のなぐり縁で結ばれた客室棟で，野﨑武吉郎の還暦記念に建設されたもの。桁行５間半，梁行４間の規模に，６畳・８畳・１０畳・便所を納め，葭葺の入母屋造屋根を架けて田舎屋風に仕立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001633"},{"id":"00001634","register_sub_id":"101","register_pk":"102624","name":"野﨑家別邸たい暇堂有藇亭附属風呂","kana":"のざきけべっていたいかどうゆうよていふぞくぶろ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島味野1-8-34","lat":34.47091228,"lng":133.8042481,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"33 － 0036","desc":"有亭の南方に位置し，有亭から片側吹放ちの渡り廊下によって接続する上客用の風呂棟。木造，平屋建，瓦葺，寄棟造で，軒先を銅板で葺く。庭側二方の腰を竹の詰打ち，鼠漆喰の壁に横縞をいれた数寄屋風の造りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001634"},{"id":"00010509","register_sub_id":"101","register_pk":"202574","name":"梅荘蔵","kana":"ばいそうくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島通生字大明神1200","lat":34.462158,"lng":133.781832,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積11㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"33 － 0271","desc":"本館の北東側に建つ。桁行二間梁間一間半の小規模な土蔵で、外壁は黒漆喰で塗込めて、上下階ともに四隅と腰部を海鼠壁とする。南面東寄りに出入口を設けて庇を付け、二階妻面の窓庇上に海鼠壁風の装飾を施し、階境にも瓦の小庇を廻らせるなど、見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010509"},{"id":"00010508","register_sub_id":"101","register_pk":"202573","name":"梅荘女中部屋及び台所","kana":"ばいそうじょちゅうべやおよびだいどころ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島通生字大明神1200","lat":34.462098,"lng":133.781886,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積108㎡","structure_material":"木造平屋一部2階建","registered":"2015.03.26(平成27.03.26)","register_no":"33 － 0270","desc":"本館の東側に接続して建つ。北に二階建の女中部屋、中央に二階建の台所、南に井戸屋を並べる。女中部屋は外壁を黒漆喰で仕上げ、南東隅には浴室を付す。台所は一階の一部を海鼠壁とし、二階は鼠漆喰で仕上げる。別荘建築における家政部の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010508"},{"id":"00010507","register_sub_id":"101","register_pk":"202572","name":"梅荘離れ","kana":"ばいそうはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島通生字大明神1200","lat":34.462106,"lng":133.781453,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"33 － 0269","desc":"本館から渡廊下を介して西方に建つ。二畳と六畳座敷を組合わせ、水屋や待合を付す。二畳の窓は梅鉢形として、網代天井を張る。座敷は半月窓や火灯窓を開けるなど気品を備える。軸部や軒廻りも吟味した丸太材などを使い、数寄屋でまとめた開放的な離れ座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010507"},{"id":"00010506","register_sub_id":"101","register_pk":"202571","name":"梅荘別館","kana":"ばいそうべっかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島通生字大明神1200","lat":34.462213,"lng":133.781685,"geo_status":"db","era":"明治前期／明治40頃移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、茅葺及び瓦葺、建築面積116㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"33 － 0268","desc":"本館から渡廊下を介して北方に建つ。入母屋造茅葺の座敷部分と、寄棟造桟瓦葺の角屋からなる。座敷部は八畳と六畳の続き座敷からなり、茅葺屋根の軒下に丸太垂木を扇に配る。角屋部分はもと化粧部屋であった。格式張らず、落ち着いた空間を表現した建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010506"},{"id":"00010505","register_sub_id":"101","register_pk":"202570","name":"梅荘本館","kana":"ばいそうほんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島通生字大明神1200","lat":34.462098,"lng":133.781674,"geo_status":"db","era":"明治40頃／平成17改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、茅葺、建築面積261㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"33 － 0267","desc":"大規模塩田を営んだ野﨑家が海水浴用に建てた別荘建築。本館は敷地中央に建ち、入母屋造茅葺の座敷部分と切妻造桟瓦葺の居間、台所部からなる。数寄屋意匠の座敷部は、車寄付の玄関と煎茶室等を附属し、平書院に丸窓を開け、欄間に波を象る瀟洒な意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010505"},{"id":"00006414","register_sub_id":"101","register_pk":"107397","name":"備中屋高祖酒造座敷蔵","kana":"びっちゅうやこうそしゅぞうざしきぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県瀬戸内市牛窓町牛窓3097-1","lat":34.61490442,"lng":134.16607052,"geo_status":"db","era":"天保年間","year":1837,"year_source":"estimated","year_min":1830,"year_max":1844,"year_label":"天保年間","structure":"土蔵造2階建、瓦葺、建築面積60㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"33 － 0164","desc":"敷地西辺に位置する土蔵造で、主屋北面から渡廊下と平屋建の前室で接続。南北棟の切妻造本瓦葺で、北半の屋根が一段高くなる。２階建土蔵で、北半にトコ付の８畳座敷を設ける。外壁は白漆喰塗で腰は海鼠壁。北に並ぶ圧搾蔵と共に段違の屋根が独特の景観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006414"},{"id":"00010510","register_sub_id":"101","register_pk":"202575","name":"姫井家住宅主屋","kana":"ひめいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県浅口市鴨方町鴨方字中山通1342","lat":34.536737,"lng":133.589917,"geo_status":"db","era":"江戸後期／明治後期・大正3改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋一部2階建、瓦葺、建築面積335㎡","structure_material":"木造平屋一部2階建","registered":"2015.03.26(平成27.03.26)","register_no":"33 － 0272","desc":"江戸時代より代々医者を輩出した旧家で、鴨方藩御殿医も務めた。ほぼ南面する主屋は桁行七間梁間五間、入母屋造桟瓦葺で、西に座敷飾を備えた座敷二室を張出す。東の突出した洋館は近代に整えられた診療室である。地方における医院建築の形態を良好に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010510"},{"id":"00010511","register_sub_id":"101","register_pk":"202576","name":"姫井家住宅長屋門","kana":"ひめいけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県浅口市鴨方町鴨方字中山通1342","lat":34.536671,"lng":133.590134,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積111㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"33 － 0273","desc":"正面道路沿いの乱石積石垣に南面して建つ土蔵造二階建で、東半部を前面に出し、棟違いの切妻造桟瓦葺とする。西半部中央に門を開き、東半部に三室を並べて北面に下屋を設け、二階は物置である。外観は漆喰塗で格子窓を並べ、風格のある屋敷景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010511"},{"id":"00005501","register_sub_id":"101","register_pk":"106489","name":"真鍋家住宅乾蔵","kana":"まなべけじゅうたくいぬいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県笠岡市真鍋島4026-1","lat":34.35493248,"lng":133.57735735,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"33 － 0109","desc":"敷地北西隅にある。南北棟の切妻造，桟瓦葺，土蔵造２階建で，南側に出入口をもつ。外壁は漆喰塗で腰を海鼠壁とし，２階部は水平に隅部は垂直に瓦を張り意匠を引き立てる。外観は近年改修されたが，旧状をよく踏襲し，伝統的な街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005501"},{"id":"00005503","register_sub_id":"101","register_pk":"106491","name":"真鍋家住宅表門","kana":"まなべけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県笠岡市真鍋島4026-1","lat":34.3546969,"lng":133.57734917,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口3.2m","structure_material":"木造","registered":"2006.03.27(平成18.03.27)","register_no":"33 － 0111","desc":"主屋前面に南面して建つ。基本的に四脚門に近い形式になるが，桁行に比して梁間を極端に狭くとり，また当初は北東隅に柱を立てない。屋根は切妻造，桟瓦葺，中央を門口とし，東脇に潜戸を設け，正面の壁には色土を用いる。旧家に相応しい表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005503"},{"id":"00005499","register_sub_id":"101","register_pk":"106487","name":"真鍋家住宅主屋","kana":"まなべけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県笠岡市真鍋島4026-1","lat":34.35478506,"lng":133.57733757,"geo_status":"db","era":"明治3","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積144㎡","structure_material":"木造平屋一部2階建","registered":"2006.03.27(平成18.03.27)","register_no":"33 － 0107","desc":"ほぼ南面して建つ東西棟の入母屋造，平屋建で，正面と背面に下屋を設け，屋根は桟瓦葺とする。平面は東側に土間を設け，街路沿いの西側に床・付書院を備えた座敷を配する。全体に丁寧なつくりである。棟札から年代が明確で，島の民家史を知る上で貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005499"},{"id":"00005502","register_sub_id":"101","register_pk":"106490","name":"真鍋家住宅倉庫及び納屋","kana":"まなべけじゅうたくそうこおよびなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県笠岡市真鍋島4026-1","lat":34.35459538,"lng":133.57756716,"geo_status":"db","era":"明治7","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造2階及び平屋建、瓦葺、建築面積55㎡","structure_material":"木造2階及び平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"33 － 0110","desc":"敷地の南東隅にある。２階建の倉庫は主屋寄りの北に位置し，この南に平屋建の納屋が並ぶ。ともに切妻造，桟瓦葺の土蔵造で，外壁は漆喰塗で腰を縦板で覆う。倉庫は麦年貢，納屋は薪木などを収納していた。屋敷構成や生活の様相を知る上で欠かせない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005502"},{"id":"00003695","register_sub_id":"101","register_pk":"104685","name":"丸本家住宅座敷屋","kana":"まるもとけじゅうたくざしきや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県浅口市鴨方町本庄字吉宗2485","lat":34.56413857,"lng":133.58909344,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"33 － 0066","desc":"接客のための座敷で，蔵に囲まれた敷地の中央に北面して建つ。強い起りをもつ主体部の桟瓦葺屋根は南面を入母屋造，北面を切妻造とし，周囲に回す本瓦葺下屋の北面には入母屋の妻を並べる。小規模だが，変化に富んだ特徴ある外観で屋敷構えの中核を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003695"},{"id":"00003696","register_sub_id":"101","register_pk":"104686","name":"丸本家住宅塀","kana":"まるもとけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県浅口市鴨方町本庄字吉宗2485","lat":34.56402902,"lng":133.58903983,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造、瓦葺、延長15m","structure_material":"木造","registered":"2003.12.01(平成15.12.01)","register_no":"33 － 0067","desc":"座敷屋の南側にある庭の南面と西面を仕切る塀。切石積基礎上に直接柱を立て，腕木で桁を受け，目板瓦葺の屋根を載せる。柱間は鼠漆喰塗で，要所に格子窓をあけ，南面では下半を竪板張とする。簡素だが端整な意匠で，座敷屋とともに屋敷中心部の構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003696"},{"id":"00001206","register_sub_id":"101","register_pk":"102196","name":"万代家住宅主屋","kana":"まんだいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県和気郡和気町原371","lat":34.79876383,"lng":134.13623807,"geo_status":"db","era":"明治5","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積194㎡","structure_material":"木造平屋建","registered":"1999.07.08(平成11.07.08)","register_no":"33 － 0030","desc":"木造平屋建，瓦葺でつし２階をつくった住宅。屋根を２重にして上層の腰下をなまこ壁とすることや下層の庇屋根の軒を一木の太い丸太材で支えるのは，この地方の通例で，その比較的に古い事例として貴重。村長を勤めた万代嘉平治の生家としても知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001206"},{"id":"00013637","register_sub_id":"101","register_pk":"505006","name":"溝手家住宅一号蔵","kana":"みぞてけじゅうたくいちごうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県都窪郡早島町早島字頓行1489","lat":34.60342778,"lng":133.82469444,"geo_status":"db","era":"弘化2年(1845)","year":1845,"year_source":"db","year_min":1845,"year_max":1845,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積59㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"33 － 0340","desc":"主屋北方に建つ東西棟の家財蔵である。裾広がりで高い切込接ぎの石積上に建つ。外壁は白漆喰塗で隅角や腰を海鼠壁とし、胴に水切瓦がつく。内部は東西二室で、それぞれ南面に戸口を開く。小屋組は地棟木に登梁を掛ける。敷地北側の景観要素として重要である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013637"},{"id":"00013634","register_sub_id":"101","register_pk":"505003","name":"溝手家住宅主屋","kana":"みぞてけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県都窪郡早島町早島字頓行1489","lat":34.60321111,"lng":133.82463889,"geo_status":"db","era":"江戸中期／弘化2年(1845)頃・万延元年(1860)増築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造2階建、茅葺一部瓦葺、建築面積494㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"33 － 0337","desc":"一七世紀から村役を務めた豪農の住宅である。入母屋造茅葺の南北棟で、東正面の入母屋造錣葺の玄関と下屋を本瓦葺とする。南東の奥座敷に矩折れの切目縁を廻す。中庭を介して西には入母屋造桟瓦葺の二階建居宅を増築した。伸びやかな屋根が外観を特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013634"},{"id":"00013639","register_sub_id":"101","register_pk":"505008","name":"溝手家住宅三号蔵","kana":"みぞてけじゅうたくさんごうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県都窪郡早島町早島字頓行1489","lat":34.60341389,"lng":133.82458889,"geo_status":"db","era":"江戸中期／弘化2年(1845)頃増築、明治42年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"土蔵造2階建、瓦葺、建築面積81㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"33 － 0342","desc":"主屋の土間西面に戸口を開く南北棟で旧は米蔵に用い、弘化頃に北方へ四柱間分増築した。切石積基礎の上に建ち、外壁は白漆喰塗で隅と腰を水平目地の海鼠壁とするが西面には横板張の部分もある。小屋組は束立と登梁を交互に組む。西方からの景観の要となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013639"},{"id":"00013635","register_sub_id":"101","register_pk":"505004","name":"溝手家住宅新座敷","kana":"みぞてけじゅうたくしんざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県都窪郡早島町早島字頓行1489","lat":34.60299444,"lng":133.82479444,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積69㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"33 － 0338","desc":"長屋門の内、主屋前庭の南に建つ客用離れ座敷である。北面玄関の南が四畳半台目の茶室で、東に床棚書院を備えた八畳座敷が続き、西から南へ欅の大板張の縁を廻す。東には風呂と便所が附属し外壁をヒシャギ竹張とする。良質な数寄屋普請が前庭の点景となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013635"},{"id":"00013641","register_sub_id":"101","register_pk":"505010","name":"溝手家住宅倉庫","kana":"みぞてけじゅうたくそうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県都窪郡早島町早島字頓行1489","lat":34.60306389,"lng":133.82508611,"geo_status":"db","era":"江戸中期／昭和40年代改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"33 － 0344","desc":"敷地の東面中央、長屋門への通路の北側に建つ南北棟の切妻造で、西面戸口の庇とも本瓦葺とする。外壁は漆喰塗で西正面と南の袖壁から南妻の腰を海鼠壁とし、外向きの東面は縦板張である。内部は一室で東半に二階床を張る。敷地導入部の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013641"},{"id":"00013642","register_sub_id":"101","register_pk":"505011","name":"溝手家住宅漬物小屋","kana":"みぞてけじゅうたくつけものごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県都窪郡早島町早島字頓行1489","lat":34.60349722,"lng":133.82491944,"geo_status":"db","era":"大正10年頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"33 － 0345","desc":"敷地の北突出部の東辺沿いに建つ。屋根は北端が寄棟造、南端が切妻造の桟瓦葺である。南から三分の一で仕切り、南室は井戸部屋を伴う。外壁は真壁造の中塗仕上である。小屋組はキングポストトラスを整然と配す。長大な建物が小路の景観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013642"},{"id":"00013643","register_sub_id":"101","register_pk":"505012","name":"溝手家住宅長屋門","kana":"みぞてけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県都窪郡早島町早島字頓行1489","lat":34.60306944,"lng":133.82496667,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"33 － 0346","desc":"東側道路に向かって開く門で入母屋造本瓦葺である。軒が高く出桁造とする。真壁造の漆喰塗で外向きとなる東面は腰を海鼠壁とする。小屋組は梁行の壁位置では梁上に束立で棟木と母屋を受け、中間は牛梁に曲がりの大きな登梁を架ける。敷地正面を重厚に飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013643"},{"id":"00013638","register_sub_id":"101","register_pk":"505007","name":"溝手家住宅二号蔵","kana":"みぞてけじゅうたくにごうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県都窪郡早島町早島字頓行1489","lat":34.60359444,"lng":133.82469722,"geo_status":"db","era":"明治37年","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"33 － 0341","desc":"敷地の北寄りに他の建物からやや離れて建つ東西棟で貴重品を蔵する。外壁は腰や妻壁を引込目地の瓦四半張として目を惹く。南面中央の戸口に切妻庇をつける。一階には建具類、二階はガラス戸棚や吊棚に器類や軸物を納める。地棟木、登梁まで鉋仕上を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013638"},{"id":"00013640","register_sub_id":"101","register_pk":"505009","name":"溝手家住宅屏風蔵","kana":"みぞてけじゅうたくびょうぶぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県都窪郡早島町早島字頓行1489","lat":34.60321944,"lng":133.82513333,"geo_status":"db","era":"慶応2年(1866)","year":1866,"year_source":"db","year_min":1866,"year_max":1866,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積111㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"33 － 0343","desc":"敷地東の道路に妻を見せる東西棟で、現在は納屋に用いる。外壁は白漆喰塗で南正面は腰を海鼠壁とし、戸口二箇所に本瓦葺の庇が付く。東妻は腰を竪板張とし上部を海鼠壁で縁取る。内部は東西二室で、西室は吹抜とする。表構えの主要な景観要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013640"},{"id":"00013636","register_sub_id":"101","register_pk":"505005","name":"溝手家住宅ビリヤード場","kana":"みぞてけじゅうたくびりやーどじょう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県都窪郡早島町早島字頓行1489","lat":34.60337778,"lng":133.82466389,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"33 － 0339","desc":"主屋の北、一号蔵との間に建つ。外壁は漆喰塗で腰を縦板張とする。東の前室は南面に戸口、東妻に出窓を設ける。床は寄木張、内壁はクロス張で腰を羽目板とし、漆喰天井に蛇腹を廻す。主室西壁にキューラックと得点盤を備える。良質な内装の洋風小建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013636"},{"id":"00000226","register_sub_id":"101","register_pk":"101216","name":"村山家住宅主屋","kana":"むらやまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島下の町二丁目1527-2","lat":34.47517487,"lng":133.82215235,"geo_status":"db","era":"明治24","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造2階建，瓦葺，建築面積159㎡","structure_material":"木造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"33 － 0016","desc":"寄棟造、桟瓦葺の大型の洋風住宅で、１・２階とも正面の半円形のアーチを置き扉口を設ける。円柱が並ぶ吹き抜けのバルコニーは、コロニアル様式となり、異国情調をよく伝える建物である。岡山県における数少ない明治洋風建築の一つで上質の建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000226"},{"id":"00001351","register_sub_id":"101","register_pk":"102341","name":"幾野家住宅主屋","kana":"いくのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県三原市久井町和草1378","lat":34.53028277,"lng":133.02533593,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積151㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"34 － 0023","desc":"もと茅葺の標準的な農家建築であるが，施主が和草村の戸長を勤めていた関係で，正面に式台玄関と，その左手に半間幅の濡れ縁をもつなど戸長役場としての性格を合わせ持つ。明治前期における地方行政機構の様子を知るうえで貴重な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001351"},{"id":"00012645","register_sub_id":"101","register_pk":"367939","name":"伊原家住宅主屋","kana":"いはらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県東広島市高屋町白市1082","lat":34.456196,"lng":132.822647,"geo_status":"geocoded","era":"大正5年頃／昭和30年頃改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積289㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"34 － 0257","desc":"白市中心部の地主宅で、主屋は街路に北面して建つ。入母屋造妻入の二階建で正面に下屋を付す。土間沿いに４室を配し、西面に座敷、南面に化粧室を接続し、随所に趣向を凝らした造作を施す。入母屋の小棟を重ね、繊細な格子が並ぶ表構えが特徴的な大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012645"},{"id":"00012646","register_sub_id":"101","register_pk":"367940","name":"伊原家住宅茶室","kana":"いはらけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県東広島市高屋町白市1082","lat":34.456196,"lng":132.822647,"geo_status":"geocoded","era":"大正前期／昭和50年頃改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、銅板葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"34 － 0258","desc":"敷地後方に北面して建つ。四畳半茶室と水屋、小間からなり、茶室は西面に床の間、北面に縁を設ける。網代天井に棹縁を付け、東半間を掛込天井とする。節付丸太の床柱、皮付丸太の鴨居や天井桁など野趣に富む数寄屋意匠で、旧家の近代の暮らしの一端を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012646"},{"id":"00012647","register_sub_id":"101","register_pk":"367941","name":"伊原家住宅門及び塀","kana":"いはらけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県東広島市高屋町白市1082","lat":34.456196,"lng":132.822647,"geo_status":"geocoded","era":"大正5年頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"門 木造、瓦葺、間口1.6m 塀 木造、瓦葺、総延長13m","structure_material":"門 木造","registered":"2018.11.02(平成30.11.02)","register_no":"34 － 0259","desc":"主屋の正面西側、座敷の前庭と街路を区切る門と塀。門は街路から後退して建つ切妻造桟瓦葺で、前後に銅板葺の庇を付す。塀は真壁造で、漆喰塗の腰縦板張とする。門の楣上にある放射状格子欄間や小壁に開く楕円形窓などに和風意匠の近代的な創意が表れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012647"},{"id":"00015375","register_sub_id":"101","register_pk":"532499","name":"伊原惣十郎家住宅主屋","kana":"いはらそうじゅうろうけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市高屋町白市1080","lat":34.45685,"lng":132.82296667,"geo_status":"db","era":"明治4年頃","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"木造2階建、瓦葺、建築面積319㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"34 - 0314","desc":"白市の本町通りに南面する鋳物商の主屋。２階建入母屋造平入桟瓦葺で、一階戸口の両脇に出格子を構え、二階窓も出格子を付す。西に土間、東に部屋を３列配し、東列は続き間座敷。一階出格子に大振りの錺金具を付す鋳物商らしい町家で本町の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015375"},{"id":"00015377","register_sub_id":"101","register_pk":"532501","name":"伊原惣十郎家住宅三階蔵","kana":"いはらそうじゅうろうけじゅうたくさんかいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県東広島市高屋町白市1080","lat":34.45693889,"lng":132.823025,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造3階建、瓦葺、建築面積23㎡","structure_material":"土蔵造3階建","registered":"2025.03.13(令和7.03.13)","register_no":"34 - 0316","desc":"主屋の北東に位置する三階建の家財蔵。切妻造妻入桟瓦葺で南面を戸口とし下屋を付す。外壁漆喰塗仕上で軒を塗込め、三段の定規筋を廻らし、腰は黒漆喰塗仕上。各階一室の板敷で東面に鉄扉付窓を開け三階は竿縁天井を張る。鋳物商の繁栄を伝える貴重な三階蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015377"},{"id":"00015376","register_sub_id":"101","register_pk":"532500","name":"伊原惣十郎家住宅離れ及び茶室","kana":"いはらそうじゅうろうけじゅうたくはなれおよびちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市高屋町白市1080","lat":34.4569,"lng":132.82311667,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積74㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"34 - 0315","desc":"主屋の北東に位置する離れ座敷と茶室。入母屋造妻入桟瓦葺の離れの西に両下造桟瓦葺の茶室を接続し全体矩折の平面とする。離れは南を式台とした三室の続き間座敷で、西に縁を付す。座敷は床と浅い床脇を構えた瀟洒なつくり。四畳半の茶室とともに上質な離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015376"},{"id":"00015378","register_sub_id":"101","register_pk":"532502","name":"伊原惣十郎家住宅門及び塀","kana":"いはらそうじゅうろうけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市高屋町白市1080-1","lat":34.45675278,"lng":132.823075,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"門 木造、瓦葺、間口2.4m 塀 木造、瓦葺、総延長13m","structure_material":"門 木造","registered":"2025.03.13(令和7.03.13)","register_no":"34 - 0317","desc":"主屋の東脇に続き、敷地南面を画す門及び塀。門は正面に石段を設けた、一間薬医門桟瓦葺で、門口に八双金具を付した両開の板扉を吊る。塀は切石積基礎に建ち、屋根桟瓦葺で外壁は漆喰塗仕上、腰は簓子下見板張。主屋に連なり歴史的な景観をつくる塀及び門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015378"},{"id":"00012644","register_sub_id":"101","register_pk":"367938","name":"榎野家住宅主屋","kana":"えのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市西条土与丸一丁目787","lat":34.427444,"lng":132.750732,"geo_status":"geocoded","era":"明治2年頃／昭和55年頃改修","year":1869,"year_source":"db","year_min":1869,"year_max":1869,"year_label":null,"structure":"木造2階建、瓦葺、建築面積94㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"34 － 0256","desc":"西条旧市街に隣接する旧土与丸村の村境にある、旧西国街道に北面して建つ町家。切妻造の二階建で正面に下屋を付す。内部は二列二室型で、通り土間に重厚な梁組をみせる。繊細な縦格子の下部に太めの横格子を入れた西条地域特有の正面出格子が特徴の町家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012644"},{"id":"00014201","register_sub_id":"101","register_pk":"508831","name":"大藤家住宅主屋","kana":"おおとうけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市高屋町白市1055","lat":34.45541389,"lng":132.82329444,"geo_status":"db","era":"昭和4年頃／昭和50年頃改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積128㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"34 - 0300","desc":"白市中心部に建つ旧酒造業の店舗兼住宅。二階建入母屋造妻入桟瓦葺で、東正面を出桁造、北側面軒廻を漆喰塗込とする。正面にガラス引違戸と格子を構え、内部は南にガラス窓を多用した開放的な通り土間、北にミセ等四室並べる。昭和初期の白市の繁栄を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014201"},{"id":"00015381","register_sub_id":"101","register_pk":"532505","name":"大藤家住宅土蔵","kana":"おおとうけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県東広島市高屋町白市1055","lat":34.45534167,"lng":132.82315,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"34 - 0320","desc":"敷地西端に位置し、南側の路地に面して建つ家財蔵。二階建切妻造妻入桟瓦葺で東面に戸口を開けて土戸を建て、外壁漆喰塗仕上で軒まで塗込める。各階板敷で内壁は中塗仕上、二階上部に二重梁の和小屋を現す。窓少なく重厚な外観で敷地西方の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015381"},{"id":"00015379","register_sub_id":"101","register_pk":"532503","name":"大藤家住宅離座敷","kana":"おおとうけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県東広島市高屋町白市1055","lat":34.45538889,"lng":132.82318333,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積76㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"34 - 0318","desc":"白市の中心部に位置する旧酒造業の離れ座敷。主屋の西に建つ、二階建片入母屋造桟瓦葺で、主屋と二階建の渡廊下で接続。一階は事務室と作業場、二階は東西の続き間座敷を配し、北と南東に廊下を廻らす。西室に床、違棚、付書院を設え、端正なつくりの離座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015379"},{"id":"00009376","register_sub_id":"101","register_pk":"194169","name":"金原家住宅主屋","kana":"かねはらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県東広島市西条町下三永字土壇原286-5","lat":34.3953122,"lng":132.75307531,"geo_status":"db","era":"大正期／平成9年移築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺一部銅板葺、建築面積231㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"34 － 0130","desc":"湖畔の敷地に建つ。木造平屋建、建築面積二三一平方メートル、入母屋造桟瓦葺で下屋を廻らし、正面に軒唐破風付の入母屋造玄関を構える。一五畳主室は座敷飾を備え吹寄折上格天井を張るほか、随所に社寺建築の細部を取入れる。材工ともに優れた近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009376"},{"id":"00009377","register_sub_id":"101","register_pk":"194170","name":"金原家住宅離れ","kana":"かねはらけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県東広島市西条町下三永字土壇原286-5","lat":34.39532505,"lng":132.75290542,"geo_status":"db","era":"大正期／平成9年移築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積31㎡、渡廊下付","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"34 － 0131","desc":"主屋西側に渡廊下を介して建ち、木造平屋建、建築面積三一平方メートル、入母屋造桟瓦葺である。トコ・棚付きの六畳主室と次の間を並べ、南側に便所を配する。便所壁に木瓜形の竹格子窓を穿ち、渡廊下には花頭窓を設けるなど小規模ながら瀟洒なつくりの離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009377"},{"id":"00009378","register_sub_id":"101","register_pk":"194171","name":"金原家住宅門","kana":"かねはらけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市西条町下三永字土壇原286-5","lat":34.395494,"lng":132.75304343,"geo_status":"db","era":"明治後期／大正期増築･平成9年移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口6.3m","structure_material":"木造","registered":"2012.08.13(平成24.08.13)","register_no":"34 － 0132","desc":"主屋玄関の北正面に建ち、木造平屋建、桁行六・三メートル梁間二・四メートル、切妻造桟瓦葺である。棟通りの中央間を間口三メートルの門口として板扉を吊り、両脇間を横板壁として西側に潜戸を開く。両側面は土壁とする。重厚な構えをもつ表門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009378"},{"id":"00011815","register_sub_id":"101","register_pk":"210831","name":"賀茂鶴酒造蓬莱庵画室棟","kana":"かもつるしゅぞうほうらいあんがしつとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県東広島市西条本町571-4他","lat":34.430854,"lng":132.746097,"geo_status":"db","era":"昭和前期／平成17年移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積93㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"34-0226","desc":"北端に座敷一五畳、その南に次の間一二畳を配し、南端に廊下を通して南西隅に玄関を置く。庭に面する北面及び西面には濡縁を廻らす。床の間は三畳畳床とし、書院周りを複雑な構成とするなど、近代的な要素の強い上質な造りである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011815"},{"id":"00000363","register_sub_id":"101","register_pk":"101353","name":"観瀾閣","kana":"かんらんかく","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県呉市下蒲刈町三之瀬字北町417-1","lat":34.19163805,"lng":132.68294072,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建，瓦葺，建築面積289㎡","structure_material":"木造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"34 － 0012","desc":"満州土木建築業協会理事長を勤めた榊谷仙次郎が建てた別荘。木造２階建で，外壁をタイル張りとする。下蒲刈島の海岸に沿った立地と中国の磚造建築の意匠を取り入れた特異な外観に特徴があり，内部の建具や欄間に用いられた技能の水準も高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000363"},{"id":"00011821","register_sub_id":"101","register_pk":"210837","name":"旧石井家住宅主屋","kana":"きゅういしいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県東広島市西条本町871","lat":34.429845,"lng":132.745068,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積171㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"34-0232","desc":"西条駅から酒造蔵が並び立つ区域への入口に建つ、木造二階建、入母屋造桟瓦葺の町屋。向かって右に土間を通し、床上部は八畳を二列三室に並べる構成。背面側は土間奥を突出させ、台所とする。西条の酒造場の住居の有り様を今に伝える建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011821"},{"id":"00011822","register_sub_id":"101","register_pk":"210838","name":"旧石井家住宅土蔵","kana":"きゅういしいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県東広島市西条本町871","lat":34.429664,"lng":132.745043,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"34-0233","desc":"主屋の背面側東寄りに建つ。土蔵造二階建で、屋根は置屋根で桟瓦を葺く。内部は上下階とも一室で、北西寄りに階段を設ける。主屋との間の庭園に面して北に扉口を開き、外壁は基礎石上に漆喰塗。簡素ではあるが、近代町屋の内蔵の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011822"},{"id":"00009827","register_sub_id":"101","register_pk":"195656","name":"旧和泉家別邸","kana":"きゅういずみけべってい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県尾道市三軒家町40-2","lat":34.40606351,"lng":133.19195491,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積50㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"34 － 0136","desc":"千光寺山南西斜面の石垣上に建つ小住宅。木造二階建で下見板張の和館の南にモルタル塗の洋館を接続する。変形の小敷地を巧みに利用しており、二階八畳座敷や階段の造作も丁寧である。入母屋屋根に切妻破風や小庇、露台をつけ、変化に富んだ屋根構成を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009827"},{"id":"00015374","register_sub_id":"101","register_pk":"532498","name":"旧小林家住宅主屋","kana":"きゅうこばやしけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県尾道市長江二丁目1125-1","lat":34.41692222,"lng":133.19875278,"geo_status":"db","era":"昭和8年／昭和45年頃増築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積172㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"34 - 0313","desc":"長江通り東側の石垣上に建ち、洋画家小林和作が晩年まで居住した主屋。二階建入母屋造平入桟瓦葺で南を玄関、西の一部を石垣上に張出し、南東に八畳と茶室を延ばし、全体を矩折の平面とする。二階はアトリエとして用い、西面に掃出窓を開けた眺望優れた主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015374"},{"id":"00008773","register_sub_id":"101","register_pk":"149494","name":"旧高橋家住宅主屋","kana":"きゅうたかはしけじゅたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県尾道市日比崎町366-2","lat":34.40471069,"lng":133.18683876,"geo_status":"db","era":"昭和8年頃／昭和30年頃増築","year":1933,"year_source":"converted","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積230㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"34 － 0114","desc":"栗原川沿いの敷地中央に東面して建つ。桁行18ｍ梁間13ｍ、木造2階建、入母屋造桟瓦葺で、南東隅に応接間と玄関を張り出す。周囲を開放的に造り、屋根は入母屋破風を複合させ、応接間に洋風意匠を採用するなど、変化のある外観になる大型住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008773"},{"id":"00004411","register_sub_id":"101","register_pk":"105401","name":"旧福井家住宅主屋","kana":"きゅうふくいけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県尾道市東土堂町１６３－１他","lat":34.40943128,"lng":133.19936066,"geo_status":"db","era":"大正元／昭和2増築","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積210㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0062","desc":"尾道水道に臨む斜面に南面して建ち，寄棟造の東棟が大正元年，入母屋造の西棟が昭和２年で，ほぼ中央の玄関を挟んで巧みに連続する。木造平屋建，桟瓦葺で，檜を中心に楓や鉄刀木などの銘木を多用した上質なつくりになり，瀟洒な数寄屋風の意匠で纏めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004411"},{"id":"00004413","register_sub_id":"101","register_pk":"105403","name":"旧福井家住宅蔵","kana":"きゅうふくいけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県尾道市東土堂町１６３－１他","lat":34.40946877,"lng":133.19926772,"geo_status":"db","era":"大正元頃","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0064","desc":"土蔵造２階建，南北棟の切妻造，妻入で，蔵前が主屋西棟の北側に連続している。規模は桁行６ｍ，梁間４ｍ，屋根は桟瓦葺，外壁は漆喰塗で，１・２階境に蛇腹風の段をつけて水切り瓦を廻す。２階妻面には小庇付の窓を設ける。主屋と一連の丁寧なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004413"},{"id":"00004412","register_sub_id":"101","register_pk":"105402","name":"旧福井家住宅茶室","kana":"きゅうふくいけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県尾道市東土堂町１６３－１他","lat":34.40940571,"lng":133.19924924,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0063","desc":"主屋西棟の北西部に連結しており，尾道の近代における茶室趣味の有様の一端を物語っている。規模は小さいが，木造平屋建，桟瓦葺で，４畳半茶室に廊下を挟んで控えの間が付属した形式になっている。主屋と同じく良材を用い，洗練された丁寧なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004412"},{"id":"00014679","register_sub_id":"101","register_pk":"515221","name":"旧宮地醤油店離れ（林芙美子旧居）","kana":"きゅうみやじしょうゆてんはなれ（はやしふみこきゅうきょ）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県尾道市土堂一丁目甲808-1他","lat":34.40568056,"lng":133.19602222,"geo_status":"db","era":"明治中期／昭和51年頃改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、鉄板葺、建築面積12㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"34 - 0305","desc":"尾道駅に程近い商店街背面側に建つ付属建物。醤油店離れや醤油蔵に利用、一時貸家とした。南北棟切妻造鉄板葺で元は瓦葺。外壁中塗仕上や鉄板張。当地では東風を避けて二階平側東面は壁とし、妻側に窓を設ける。尾道の短冊形敷地裏手に建つ付属建物の典型。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014679"},{"id":"00000170","register_sub_id":"101","register_pk":"101160","name":"呉市入船山記念館休憩所（旧東郷家住宅離れ）","kana":"くれしいりふねやまきねんかんきゅうけいじょ（きゅうとうごうけじゅうたくはなれ）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県呉市幸町4-6","lat":34.23950293,"lng":132.5642033,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建，瓦葺，建築面積37㎡","structure_material":"木造平屋建","registered":"1997.05.07(平成9.05.07)","register_no":"34 － 0006","desc":"元は呉市宮原通りの正円寺前にあった邸宅の離れであり，一時期東郷平八郎が居を定めていた。その後移築され，空家となって荒廃していたが，昭和55年に市によって再度移築された。8畳と6畳の二間に廊下が付く構成で，海軍ゆかりの施設として広く知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000170"},{"id":"00012044","register_sub_id":"101","register_pk":"210985","name":"桑田家住宅石垣及び塀","kana":"くわだけじゅうたくいしがきおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県府中市本山町字東谷ヨリムネ1517-1","lat":34.595172,"lng":133.245757,"geo_status":"db","era":"明治後期／昭和前期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石垣 石造、延長38m 塀 土塀、瓦葺、延長36m","structure_material":"石垣 石造","registered":"2017.10.27(平成29.10.27)","register_no":"34-245","desc":"急傾斜地である敷地の前面に位置し、石垣は六メートル超と高く積み、塀は高さ九五センチメートルから七五センチメートルの漆喰塗に瓦葺とする。石垣は打込み接ぎの精緻なもので、ひときわ高い外観で地域の景観を特徴付けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012044"},{"id":"00012042","register_sub_id":"101","register_pk":"210983","name":"桑田家住宅主屋","kana":"くわだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県府中市本山町字東谷ヨリムネ1517-1","lat":34.595292,"lng":133.245667,"geo_status":"db","era":"江戸末期／明治前期・昭和前期・同42年頃・平成26年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（鋼板仮葺）、建築面積174㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"34-243","desc":"崖地に高い石垣を築いて整形した土地に建つ農家。江戸末期の当地方における大型農家の標準的な平面を持つ。床の間等は近代の改造で設けられたもの。屋根は入母屋造の茅葺で、現在鉄板で覆われている。地域の近世以来の歴史を今に伝える建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012042"},{"id":"00012043","register_sub_id":"101","register_pk":"210984","name":"桑田家住宅離れ","kana":"くわだけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県府中市本山町字東谷ヨリムネ1517-1","lat":34.595331,"lng":133.245518,"geo_status":"db","era":"昭和16年","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積65㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"34-244","desc":"主屋の西側に建つ。木造平屋建、入母屋造桟瓦葺で、外壁は黒漆喰塗。内部は一〇畳座敷と六畳次の間の東と南に縁を廻らし、西側に便所を突出させる。座敷には琵琶床を設け、床柱はスギの磨き丸太とするなど、細部意匠にも凝る離れで、地域の景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012043"},{"id":"00003599","register_sub_id":"101","register_pk":"104589","name":"耕三寺潮聲閣","kana":"こうさんじちょうせいかく","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.30485428,"lng":133.09084697,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造及び鉄筋コンクリート造平屋一部2階建、瓦葺、建築面積389㎡","structure_material":"木造及び鉄筋コンクリート造平屋一部2階建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0057","desc":"境内東北隅に建つ住宅建築。ポーチを持つＲＣ造２階建の洋館と，唐破風の玄関を持つ木造平屋建の和館からなり，洋館，和館玄関，老人室など各所に意匠を凝らす。洋館と和館を並立させる昭和初期の大規模住宅建築の特徴をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003599"},{"id":"00013645","register_sub_id":"101","register_pk":"505014","name":"眞田家住宅奥座敷","kana":"さなだけじゅうたくおくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県三原市東町一丁目416-1","lat":34.40134722,"lng":133.08842222,"geo_status":"db","era":"昭和3年／昭和38年増築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積171㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0285","desc":"主屋の南東に建つ平屋建の東西二棟からなる。東棟は東西に二室、西棟は南北に二室を並べ、いずれも北南面に縁を通して連絡する。東棟の大広間は東に床、東北に床脇を矩折れに配し、南に付書院を備える。造作に銘木を多用し、意匠を凝らした近代和風の座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013645"},{"id":"00013649","register_sub_id":"101","register_pk":"505018","name":"眞田家住宅表門","kana":"さなだけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県三原市東町一丁目416-1","lat":34.40161667,"lng":133.08845833,"geo_status":"db","era":"昭和3年／平成14年移築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造、銅板葺、間口2.4m","structure_material":"木造","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0289","desc":"敷地北面東寄りに建つ、切妻造銅板葺の薬医門。桁行一間で、角柱の上に冠木を載せ、挿肘木と斗で女梁・男梁を受け、軒桁を架ける。棟木は本蟇股で受け、軒は一軒疎垂木とする。柱間に扉を吊り、内法上は筬欄間とする。敷地北面の屋敷構えを形成する表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013649"},{"id":"00013644","register_sub_id":"101","register_pk":"505013","name":"眞田家住宅主屋","kana":"さなだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県三原市東町一丁目416-1","lat":34.40155556,"lng":133.08827222,"geo_status":"db","era":"大正前期／昭和38年・平成14年改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階一部平屋建、瓦葺一部銅板葺、建築面積250㎡","structure_material":"木造2階一部平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0284","desc":"旧山陽道に北面して建つ二階建、切妻造平入で、南に平屋建が続き、東面北端に入母屋造屋根の玄関を配す。一階を出格子、二階に虫籠窓を開けた黒漆喰塗の重厚な外観を持つ。内部は西を通り土間、東を床上部とし、東・南面に縁を廻して庭を臨む景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013644"},{"id":"00013646","register_sub_id":"101","register_pk":"505015","name":"眞田家住宅客間","kana":"さなだけじゅうたくきゃくま","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県三原市東町一丁目416-1","lat":34.40133611,"lng":133.08826111,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階一部平屋建、瓦葺一部銅板葺、建築面積109㎡","structure_material":"木造2階一部平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0286","desc":"主屋の南側、奥座敷の西側に建つ二階建寄棟造。一階は南の庭側へ突出する平屋部を含んで一室の洋間とし、床を寄木張、南、西面に三連窓を開ける。二階は二室の座敷とし、南から東に高欄付縁を廻らし、庭を臨む。和洋の接客空間を巧みに組み合わせた客間棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013646"},{"id":"00013647","register_sub_id":"101","register_pk":"505016","name":"眞田家住宅茶室","kana":"さなだけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県三原市東町一丁目416-1","lat":34.40144444,"lng":133.08849722,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0287","desc":"奥座敷棟の北に廊下で接続する茶室。庭側の西面を入母屋造、東面を切妻造とした桟瓦葺で、北に切妻造桟瓦葺の水屋が続き、西面に銅板葺庇を付け、待合を配す。茶室は六畳で北に点前座、東に床、南に躙口を設ける。屋根と庇により外観に変化を付けた茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013647"},{"id":"00013648","register_sub_id":"101","register_pk":"505017","name":"眞田家住宅土蔵","kana":"さなだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県三原市東町一丁目416-1","lat":34.40118333,"lng":133.088475,"geo_status":"db","era":"大正前期／昭和3年増築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造2階建及び煉瓦造3階建、瓦葺、建築面積85㎡","structure_material":"土蔵造2階建及び煉瓦造3階建","registered":"2021.02.04(令和3.02.04)","register_no":"34 － 0288","desc":"奥座敷の南に廊下で接続して建ち、北の二階建土蔵造と南の三階建煉瓦造からなる。いずれも南北棟の切妻造桟瓦葺とし、外壁は二棟一体で漆喰塗仕上とする。北面が戸口で、内部は一階のみ連絡し、小屋組はいずれも和小屋とする。敷地南東の屋敷構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013648"},{"id":"00000364","register_sub_id":"101","register_pk":"101354","name":"松籟亭","kana":"しょうらいてい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県呉市下蒲刈町下島字池之浦3158","lat":34.1748905,"lng":132.67487389,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積81㎡","structure_material":"木造平屋建","registered":"1997.11.05(平成9.11.05)","register_no":"34 － 0013","desc":"満鉄に関連する車両会社の社長が接待用に建設した「万里荘」の離れ座敷として建てられた。数多くの数寄屋を手がけた平田雅哉の初期の作品で，栗のナグリ仕上げの広縁や吟味された材料を用いた３畳台目の茶席に見るべきものがある。平成４年に現在地に移築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000364"},{"id":"00001375","register_sub_id":"101","register_pk":"102365","name":"白滝山荘（旧ファーナム住宅）","kana":"しらたきさんそう（きゅうふぁーなむじゅうたく）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県尾道市因島重井町伊浜1233","lat":34.34465872,"lng":133.15418286,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造一部鉄筋コンクリート造3階建、瓦葺、建築面積105㎡","structure_material":"木造一部鉄筋コンクリート造3階建","registered":"1999.10.14(平成11.10.14)","register_no":"34 － 0022","desc":"因島北部の白滝山の登山口に位置するもとアメリカ人宣教師の居宅で，斜面に建ち，１階を鉄筋コンクリート造，２階・３階を木造とする。急傾斜屋根にドーマー窓を付けたハーフティンバー・スタイルの洋館で，ヴォーリズ建築事務所の作風の一端をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001375"},{"id":"00012244","register_sub_id":"101","register_pk":"353044","name":"瀧口家住宅裏門及び土塀","kana":"たきぐちけじゅうたくうらもんおよびどべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県庄原市春田町字岩見1-1","lat":34.81596864,"lng":133.04497194,"geo_status":"db","era":"明治35年頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"裏門 木造、瓦葺、柱間2.5m 土塀 瓦葺、総延長115m","structure_material":"裏門 木造","registered":"2018.03.27(平成30.03.27)","register_no":"34-253","desc":"裏門は敷地南面に開く。東半間に袖壁を設け、西一間に両開板扉を吊り、西端のみに控柱を立てる非対称な構え。土塀は、亀甲積の石垣上に建ち、総延長一一五メートルにも及ぶ。医師を迎えるため村民の夫役により造成されたもので、歴史的な景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012244"},{"id":"00012242","register_sub_id":"101","register_pk":"353042","name":"瀧口家住宅木小屋","kana":"たきぐちけじゅうたくきごや","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県庄原市春田町字岩見1-1","lat":34.815775,"lng":133.045457,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"34-251","desc":"納屋に直交して建つ。桁行五間、梁間二間で、北面は下屋取り込む。土蔵造二階建で、一階は東半を吹放ち薪炭置き場とし、西半は漬物小屋である。二階は養蚕に使用した。雪国において生活を支える施設であり、土塀と一体となり敷地南東隅を画す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012242"},{"id":"00012238","register_sub_id":"101","register_pk":"353038","name":"瀧口家住宅客殿及び渡廊下","kana":"たきぐちけじゅうたくきゃくでんおよびわたりろうか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"広島県","address":"広島県庄原市春田町字岩見1-1","lat":34.816068,"lng":133.045098,"geo_status":"db","era":"大正15年頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"客殿 木造平屋建、瓦葺、建築面積113㎡ 渡り廊下 木造平屋建、瓦葺、建築面積22㎡","structure_material":"客殿 木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"34-247","desc":"主屋の西方に渡廊下で接続する。渡廊下は中央の壁で南北に分かれ、北は客室となる座敷へ、南は主人の書斎や便所へ繋がる。座敷は良材を用い、戸袋まで意匠を凝らす。客殿は平屋建であるが建ちが高く、入母屋造の屋根に鯱瓦を載せ、重厚な外観をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012238"},{"id":"00012237","register_sub_id":"101","register_pk":"353037","name":"瀧口家住宅主屋","kana":"たきぐちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県庄原市春田町字岩見1-1","lat":34.815969,"lng":133.045339,"geo_status":"db","era":"大正2年","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積386㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"34-246","desc":"山陰と山陽を結ぶ交通の要衝に建つ。正面中央に式台玄関を設け、広大な土間と床上部に八室を配す。公的な座敷と私的な居室を前後で区分し、二階に家族用の座敷をもつ。式台玄関の虹梁や出格子に整った意匠をみせ、座敷飾りなど随所に大工の技量が発揮される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012237"},{"id":"00012243","register_sub_id":"101","register_pk":"353043","name":"瀧口家住宅中門及び袖塀","kana":"たきぐちけじゅうたくちゅうもんおよびそでべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県庄原市春田町字岩見1-1","lat":34.8161053,"lng":133.0453719,"geo_status":"db","era":"大正2年頃","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"中門 木造、瓦葺、間口1.7m 袖塀 木造、瓦葺、総延長12m","structure_material":"中門 木造","registered":"2018.03.27(平成30.03.27)","register_no":"34-252","desc":"主屋から長屋門へ南北棟で建ち、主屋の玄関前と座敷や客殿の庭園を区画する。中門は、間口一・七メートルの薬医門で、切妻造桟瓦葺。袖塀は木造で、腕木で桁を支持する。柱、楣、桁、垂木まで丸太材が用いられ数寄屋風意匠であるが、木割は太く堂々たる構え。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012243"},{"id":"00012240","register_sub_id":"101","register_pk":"353040","name":"瀧口家住宅土蔵","kana":"たきぐちけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県庄原市春田町字岩見1-1","lat":34.815995,"lng":133.04558,"geo_status":"db","era":"大正期／昭和後期改修","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積58㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"34-249","desc":"敷地東面に建つ。桁行九・八メートル、梁間五・九メートル、土蔵造二階建で切妻造の置屋根形式。中央に柱を立て、一階は土間で栗材を用い、二階は松材を用いる。外壁は漆喰塗で鉢巻を廻らす。土塀と一体となり前面道路からの景観を構成する上で重要である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012240"},{"id":"00012239","register_sub_id":"101","register_pk":"353039","name":"瀧口家住宅納戸","kana":"たきぐちけじゅうたくなんど","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県庄原市春田町字岩見1-1","lat":34.815849,"lng":133.045257,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積57㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"34-248","desc":"主屋南側の角屋から縁を介して接続する。木造平屋建、東西棟の切妻造。一階に二室を設け、つし二階は曲り梁を現しとして、家財道具の倉庫にあてる。便所や風呂も往時の姿をよく留める内向きの施設であり、本村川に面する敷地背面の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012239"},{"id":"00007132","register_sub_id":"101","register_pk":"108114","name":"信岡家住宅井戸屋形","kana":"のぶおかけじゅうたくいどやかた","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"広島県","address":"広島県福山市新市町大字戸手2166","lat":34.5489278,"lng":133.29777738,"geo_status":"db","era":"慶応4","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造、瓦葺、面積5.6㎡","structure_material":"木造","registered":"2008.04.18(平成20.04.18)","register_no":"34 － 0090","desc":"主屋の東南方に位置し、東西棟で建つ。桁行３．１ｍ梁間１．８ｍ規模、寄棟造桟瓦葺で、西寄りの石造井戸と東側の石敷の洗い場を覆う。洗い場側の東面の柱は礎石建とし、南・北両面には差物、東・西両面には上下を開けた腰壁を入れた特徴あるつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007132"},{"id":"00007127","register_sub_id":"101","register_pk":"108109","name":"信岡家住宅主屋","kana":"のぶおかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県福山市新市町大字戸手2166","lat":34.54899042,"lng":133.29757772,"geo_status":"db","era":"文政9","year":1826,"year_source":"db","year_min":1826,"year_max":1826,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積346㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"34 － 0085","desc":"旧福山府中街道に南面する屋敷地の北寄りに東西棟で建つ。段違切妻造桟瓦葺のつし２階建で、東方を土間、西方を床上部とし、さらに西に本願寺下賜の仏壇を納める座敷棟を延ばし、桁行２９ｍ規模とする。地方における有力真宗門徒の住宅の様相を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007127"},{"id":"00007130","register_sub_id":"101","register_pk":"108112","name":"信岡家住宅炭小屋","kana":"のぶおかけじゅうたくすみごや","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"low","period":"江戸","pref":"広島県","address":"広島県福山市新市町大字戸手2166","lat":34.54903076,"lng":133.29788207,"geo_status":"db","era":"江戸末期／昭和初期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積27㎡、塀付","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"34 － 0088","desc":"主屋の東方、東の蔵の北方に東西棟で建つ。桁行６．９ｍ梁間３．９ｍ規模、切妻造桟瓦葺、平屋建で、南面に材木を置くための棚を設ける。「操出記録」に記載のある「東脇木納屋」にあたる建屋とみられ、近世の信岡家の生活様態の一端を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007130"},{"id":"00007131","register_sub_id":"101","register_pk":"108113","name":"信岡家住宅茶室及び腰掛","kana":"のぶおかけじゅうたくちゃしつおよびこしかけ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県福山市新市町大字戸手2166","lat":34.54887552,"lng":133.29741884,"geo_status":"db","era":"昭和初期／昭和30頃移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"茶室 木造平屋建、茅葺（銅板仮葺）、建築面積18㎡ 腰掛 木造、銅板葺、面積3.5㎡","structure_material":"茶室 木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"34 － 0089","desc":"主屋座敷棟の南に位置し、西方に腰掛を配する。茶室は南北棟、入母屋造茅葺（銅板仮葺）で、６畳大の主室、背後の３畳大水屋からなり、南西角に南面して躙口、西面して貴人口を開ける。速水流家元の設計と伝える。近代田舎屋風茶室の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007131"},{"id":"00007133","register_sub_id":"101","register_pk":"108115","name":"信岡家住宅中門及び塀","kana":"のぶおかけじゅうたくちゅうもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県福山市新市町大字戸手2166","lat":34.54883727,"lng":133.29751156,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"門 木造、瓦葺、間口1.5m 塀 木造、瓦葺、延長10m","structure_material":"門 木造","registered":"2008.04.18(平成20.04.18)","register_no":"34 － 0091","desc":"茶室の東南方に位置し、南北棟で建ち、南北に塀を延ばす。間口１．５ｍ、切妻造桟瓦葺の１間腕木門で前後に控柱を建てる。茶室の場所に建っていた御成座敷のための門と伝えられ、妻飾りや菱欄間の意匠、板扉の金具等に御成門としての格式を感じさせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007133"},{"id":"00007134","register_sub_id":"101","register_pk":"108116","name":"信岡家住宅長屋門","kana":"のぶおかけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県福山市新市町大字戸手2166","lat":34.54881469,"lng":133.29774328,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積137㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"34 － 0092","desc":"主屋の南方、屋敷の正面に東西棟で建つ。桁行３１ｍ梁間４．０ｍ規模、入母屋造本瓦葺の２階建で、西寄りに門口を開け、北面に土庇を付ける。東端３間半は大壁造の米倉で、門口両脇に使用人の居室を配する。たちが高く、旧福山府中街道沿いの目印となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007134"},{"id":"00007129","register_sub_id":"101","register_pk":"108111","name":"信岡家住宅西の蔵","kana":"のぶおかけじゅうたくにしのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県福山市新市町大字戸手2166","lat":34.54898886,"lng":133.29731469,"geo_status":"db","era":"文化5","year":1808,"year_source":"db","year_min":1808,"year_max":1808,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積66㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"34 － 0087","desc":"主屋の西方に位置し、東西棟で建つ。桁行１３ｍ梁間５．１ｍ規模、切妻造本瓦葺、２階建の道具蔵で、内部は東・西２室に分け、東から南面に桟瓦葺の庇をまわし、東面と南面に戸口を設ける。腰部や庇上部等に意匠の異なる海鼠壁として変化をもたせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007129"},{"id":"00007128","register_sub_id":"101","register_pk":"108110","name":"信岡家住宅東の蔵","kana":"のぶおかけじゅうたくひがしのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県福山市新市町大字戸手2166","lat":34.54892938,"lng":133.29788517,"geo_status":"db","era":"文政9","year":1826,"year_source":"db","year_min":1826,"year_max":1826,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積66㎡、東門付","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"34 － 0086","desc":"主屋の南東方に位置し、南北棟で建つ。桁行１３ｍ梁間５．１ｍ、切妻造本瓦葺の２階建土蔵で、もと米蔵と伝え、内部は南・北に分け、西面に土間庇、東南端に東門を付す。外部は黒漆喰塗で腰部や水切りの小庇の上部等に海鼠壁をまわした重厚なつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007128"},{"id":"00001952","register_sub_id":"101","register_pk":"102942","name":"延藤家住宅洋館","kana":"のぶとうけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県府中市出口町37-1","lat":34.57887613,"lng":133.23096075,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積48㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"34 － 0034","desc":"和館部の玄関脇に建つ応接用の施設。一階を擬石塗り，二階をハーフティンバーとし，南面にベイウインドウを設け，西面では一階に出窓を造りその上を二階バルコニーとする。小規模ながら華やかな外観をもち，内部の階段廻りなどにも斬新な意匠がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001952"},{"id":"00001953","register_sub_id":"101","register_pk":"102943","name":"延藤家住宅和館（洞仙荘）","kana":"のぶとうけじゅうたくわかん（どうせんそう）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県府中市出口町37-1","lat":34.5788191,"lng":133.23081596,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積360㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"34 － 0035","desc":"南面する傾斜地に建てられた別荘施設で，和館部は２階建の主体部と渡り廊下で続く離れからなる。玄関奥の二間続きの座敷は数寄屋風の意匠でまとめられ，これに接して四畳半の茶室を備える。複雑にかかる屋根によって，変化に富んだ瀟洒な外観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001953"},{"id":"00014946","register_sub_id":"101","register_pk":"519206","name":"林家住宅主屋","kana":"はやしけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県福山市鞆町鞆字鍛冶町271","lat":34.385625,"lng":133.38210278,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積215㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"34 - 0306","desc":"鞆城跡北東の角地に位置し、かつて醸造業や廻船業で栄えた商家の町家。通りに東面する二階建入母屋造平入本瓦葺で外壁は黒漆喰塗仕上で軒を現す。一階出隅は出格子構えとし、二階壁面は広い縁取の木瓜形虫籠窓を並べて腰を海鼠壁とするなど豪壮な意匠の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014946"},{"id":"00003310","register_sub_id":"101","register_pk":"104300","name":"飛弾家住宅蔵","kana":"ひだけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県呉市豊町大長5368","lat":34.180756,"lng":132.85437,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"土蔵造平屋建、瓦葺、建築面積70㎡","structure_material":"土蔵造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"34 － 0040","desc":"主屋と中庭を挟んだ南側にある。木造平屋建，東西棟の切妻造，平入で，主屋側の北面に蔵前の庇を設ける。２階建の高さをもつが，内部は床・天井のない倉庫空間としており，当初よりみかんの保存用に建てられたことが知られ，みかん栽培の地域色を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003310"},{"id":"00003309","register_sub_id":"101","register_pk":"104299","name":"飛弾家住宅蔵門","kana":"ひだけじゅうたくくらもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県呉市豊町大長5368","lat":34.18106765,"lng":132.85449777,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造2階建、瓦葺、建築面積121㎡","structure_material":"木造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"34 － 0039","desc":"屋敷東辺を画す長屋門風の建物で，北側は主屋に接する。木造２階建，入母屋造，桟瓦葺で，１階中央部を門口とし，各階を小部屋に仕切り，倉庫に用いる。道路に面した東面は真壁造だが，１階を腰を簓子下見板張とするなど，大正期の意匠のあり方を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003309"},{"id":"00003307","register_sub_id":"101","register_pk":"104297","name":"飛弾家住宅主屋","kana":"ひだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県呉市豊町大長5368","lat":34.181072,"lng":132.854355,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積144㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"34 － 0037","desc":"不整形の屋敷地北側にあり，文化９年没の当家３代目平三良が建てたと伝える。木造つし２階建，東西棟の切妻造，平入で，南・北・西の３方に下屋を廻し，屋根は全て本瓦葺とする。軒廻りの漆喰塗込や下屋の登り梁風の差し掛け梁など，丁寧なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003307"},{"id":"00003308","register_sub_id":"101","register_pk":"104298","name":"飛弾家住宅離れ","kana":"ひだけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県呉市豊町大長5368","lat":34.18095,"lng":132.854263,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積148㎡","structure_material":"木造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"34 － 0038","desc":"主屋の西南，東を向いて建つ。木造２階建，入母屋造，桟瓦葺で，１階は２階よりひとまわり大きく，庇を廻して東面に入母屋造の玄関を設ける。玄関は柱を狛犬風石製礎盤で受け，軒に丸垂木を用いるなど，要所に数寄屋風細部を配した瀟洒な意匠でまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003308"},{"id":"00010898","register_sub_id":"101","register_pk":"201733","name":"日野家住宅御成門","kana":"ひのけじゅうたくおなりもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県安芸高田市甲田町深瀬字久住甲172・乙172合併","lat":34.736158,"lng":132.781613,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、銅板葺、間口1.7m","structure_material":"木造","registered":"2015.11.17(平成27.11.17)","register_no":"34 ‐ 0155","desc":"主屋西端間の御成座敷に対して南正面に建つ。間口一・七メートルの一間腕木門で、上部に襷桟の欄間を嵌める。門扉は八双金物を用いて板戸を吊る。主屋のもと御成座敷前の主庭と前庭を区画する境界装置で、気品ある佇まいを見せて敷地内景観を引き立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010898"},{"id":"00010897","register_sub_id":"101","register_pk":"201732","name":"日野家住宅表門及び伴部屋","kana":"ひのけじゅうたくおもてもんおよびともべや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県安芸高田市甲田町深瀬字久住甲172・乙172合併","lat":34.736031,"lng":132.781893,"geo_status":"db","era":"元治元頃／明治前期移築","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"表門 木造、瓦葺、間口3.6m、西方潜り戸付 伴部屋 木造平屋建、瓦葺、建築面積13㎡","structure_material":"表門 木造","registered":"2015.11.17(平成27.11.17)","register_no":"34 ‐ 0154","desc":"敷地の南正面に建つ。腕木門形式の表門の西方に、潜り戸を介して、平屋建の伴部屋が番所のように接続する。表門は木太く端正な佇まいで、広島新田藩吉田陣屋の門を移したとされる。伴部屋は正面に出格子窓を付ける。屋敷の表構えに風格のある趣を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010897"},{"id":"00010893","register_sub_id":"101","register_pk":"201728","name":"日野家住宅米倉","kana":"ひのけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県安芸高田市甲田町深瀬字久住甲172・乙172合併","lat":34.736069,"lng":132.781722,"geo_status":"db","era":"昭和2頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積109㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"34 ‐ 0150","desc":"敷地南方、表門の西に、南に流れる川に面して建つ二階建の土蔵。内部は二室に分かれ、それぞれ北方に鳥居型の枠を持つ出入口を設ける。もとは精米所や炊事場などを併設していた。宅地の表構えの一部を成す建物で、集落の歴史的な景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010893"},{"id":"00010891","register_sub_id":"101","register_pk":"201726","name":"日野家住宅主屋","kana":"ひのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県安芸高田市甲田町深瀬字久住甲172・乙172合併","lat":34.736309,"lng":132.7817,"geo_status":"db","era":"安永8頃／昭和11改修","year":1779,"year_source":"db","year_min":1779,"year_max":1779,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積441㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"34 ‐ 0148","desc":"敷地中央に南面する。東の土間は重厚な梁組を現し、西の床上部は四列に四室前後を並べた広さをもつ。一二畳の前側に茶室を設け、鍵型の座敷に縁を廻らし、上部には採光窓を設ける。近世民家の主構造を保持しつつ、近代らしい洗練さと開放性を併せもつ大型住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010891"},{"id":"00010895","register_sub_id":"101","register_pk":"201730","name":"日野家住宅酒造倉","kana":"ひのけじゅうたくしゅぞうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県安芸高田市甲田町深瀬字久住甲172・乙172合併","lat":34.736478,"lng":132.781617,"geo_status":"db","era":"享保18／大正前期移築","year":1733,"year_source":"db","year_min":1733,"year_max":1733,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積214㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"34 ‐ 0152","desc":"納戸倉の東に接して東西棟で建つ。納戸倉同様、桁行二二メートルの大型の二階建土蔵で、外壁漆喰塗とし、南面東寄りに塗戸を開く。内部柱は二本のみとして広壮な空間をもつ。近世から生業とした酒造業を担った土蔵で、連なる納戸倉とともに雄大な屋敷構えを創る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010895"},{"id":"00010896","register_sub_id":"101","register_pk":"201731","name":"日野家住宅納屋","kana":"ひのけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県安芸高田市甲田町深瀬字久住甲172・乙172合併","lat":34.736298,"lng":132.782102,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積99㎡、門付","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"34 ‐ 0153","desc":"敷地の東方に南北棟で建ち、桁行一七メートル規模で壁を真壁造とする。もとは北半を資材納屋、南半を牛舎として使用し、北半は吹抜けの一層、南半は二階建の上階を飼料置場とした。さらに南には、敷地東辺を画す門を附属する。田園越しの屋敷景観を引立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010896"},{"id":"00010894","register_sub_id":"101","register_pk":"201729","name":"日野家住宅納戸倉及び離れ","kana":"ひのけじゅうたくなんどぐらおよびはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県安芸高田市甲田町深瀬字久住甲172・乙172合併","lat":34.736421,"lng":132.781446,"geo_status":"db","era":"納戸倉 元禄15頃／大正前期移築 離れ 大正前期","year":1702,"year_source":"db","year_min":1702,"year_max":1702,"year_label":null,"structure":"土蔵造2階建及び木造平屋建、瓦葺、建築面積199㎡","structure_material":"土蔵造2階建及び木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"34 ‐ 0151","desc":"主屋の北方西寄りに、離れを介して東西棟の納戸倉が建つ。離れは六畳二室と板間に縁を廻らせた開放的なつくり。納戸倉は桁行二二メートルを測る大型の二階建土蔵で、深い軒を方杖で支持する。充実した規模を誇り、漆喰で塗込めた長大な外壁が田園風景に映える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010894"},{"id":"00010892","register_sub_id":"101","register_pk":"201727","name":"日野家住宅洋館","kana":"ひのけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県安芸高田市甲田町深瀬字久住甲172・乙172合併","lat":34.736279,"lng":132.781902,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積92㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"34 ‐ 0149","desc":"主屋南東に接続して建つ。外壁は横板張で欄間付の上下窓を並べ、寄棟造桟瓦葺とする。南面中央の出入口に幾何意匠の持送付庇を付す。一階に事務室と応接室、二階に集会室を配し、窓の室内側に和紙のロールブラインドなどを残す。瀟洒な意匠でまとめた洋館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010892"},{"id":"00000264","register_sub_id":"101","register_pk":"101254","name":"福山市福寿会館","kana":"ふくやましふくじゅかいかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県福山市丸之内1-1-1","lat":34.491907,"lng":133.3615144,"geo_status":"db","era":"昭和10～12頃","year":1935,"year_source":"converted","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建，瓦葺，建築面積138㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"34 － 0008","desc":"個人の別荘として建てられた木造，２階建ての洋館。屋根を急勾配とし外壁をモルタル塗りとした，立ちの高い外観に，昭和初期の洋風の住宅建築の特徴がよくあらわれている。庭に面した側の妻にある中央部の浮き彫り装飾や窓上部のアーチ形装飾が美しい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000264"},{"id":"00009220","register_sub_id":"101","register_pk":"164773","name":"福山市福寿会館西蔵","kana":"ふくやましふくじゅかいかんにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県福山市丸之内1-1-1他","lat":34.4920698,"lng":133.36111278,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積59㎡","structure_material":"土蔵造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"本館北西側に廊下で接続する内蔵である。桁行9.9メートル梁間6.0メートル、土蔵造2階建、切妻造妻入で、本瓦葺の屋根に起りをもたせる。布石積の基礎上に建ち、外壁は漆喰塗で各階の腰に海鼠壁を廻す。建ちの高い土蔵で、敷地北西の景観を引締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009220"},{"id":"00009218","register_sub_id":"101","register_pk":"164771","name":"福山市福寿会館西茶室","kana":"ふくやましふくじゅかいかんにしちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県福山市丸之内1-1-1他","lat":34.49198057,"lng":133.36112943,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺及び檜皮葺、建築面積67㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"本館西側に渡廊下を介して建ち、木造平屋建、建築面積67平方メートル、寄棟造桟瓦及び檜皮葺である。天守を望む10畳主室の西側に3畳台目茶室、北側に2畳中板付茶室を配し、水屋を舟底天井とする。本館との調和がはかられた、瀟洒なつくりの数寄屋建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009218"},{"id":"00009221","register_sub_id":"101","register_pk":"164774","name":"福山市福寿会館東蔵","kana":"ふくやましふくじゅかいかんひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県福山市丸之内1-1-1他","lat":34.49214118,"lng":133.36149825,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"本館の北東に位置し、桁行6.9メートル梁間3.9メートル、土蔵造2階建、切妻造本瓦葺である。布石積の基礎上に建ち、外壁は漆喰塗で各階の腰に海鼠壁を廻す。1階南半は土間で、主屋台所に通じる西側に出入口を開く。邸宅内で日用に供した土蔵の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009221"},{"id":"00009217","register_sub_id":"101","register_pk":"164770","name":"福山市福寿会館本館","kana":"ふくやましふくじゅかいかんほんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県福山市丸之内1-1-1他","lat":34.49203292,"lng":133.36134358,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺及び檜皮葺、建築面積385㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"福山城北側の敷地北寄りに建つ。木造平屋建、建築面積385平方メートル、入母屋造桟瓦及び檜皮葺で、正面に唐破風造檜皮葺の玄関を構える。21畳主室と次の間に縁を廻らし、主室は大振りで上質な座敷飾りを備える。庭園越しの天守眺望を意図した和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009217"},{"id":"00009219","register_sub_id":"101","register_pk":"164772","name":"福山市福寿会館南茶室","kana":"ふくやましふくじゅかいかんみなみちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県福山市丸之内1-1-1他","lat":34.4915713,"lng":133.36165291,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺及び檜皮葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"池を挟んで本館の南側に建つ茶室で、望城亭とも呼ばれる。木造平屋建、建築面積78平方メートル、桟瓦及び檜皮葺で、3畳台目の小間と8畳の広間を庭園側に配し、裏手に水屋などをおく。京都の数寄屋大工笛吹嘉一郎の手になる、意匠洗練で開放的な近代茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009219"},{"id":"00014202","register_sub_id":"101","register_pk":"508832","name":"保手濱家住宅主屋","kana":"ほてはまけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市高屋町白市1047-1","lat":34.45602778,"lng":132.82349167,"geo_status":"db","era":"明治17年／昭和50年頃改修","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造2階建、瓦葺、建築面積119㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"34-0301","desc":"白市中心部に西面して建つ町家。つし二階建、切妻造平入桟瓦葺、正面に一間半の下屋を葺下す。二階つし部分は奥行二間。中央に玄関を構えて廊下を通し、南北各三室を並べるが廊下、正面側の部屋はもと土間と伝わる。西条盆地の町家の変遷を伝える重要な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014202"},{"id":"00011558","register_sub_id":"101","register_pk":"210493","name":"三宅家住宅衣裳蔵","kana":"みやけけじゅうたくいしょうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県安芸郡海田町稲荷町184","lat":34.37349389,"lng":132.53317194,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積63㎡","structure_material":"土蔵造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"34-0208","desc":"南北に細長い敷地の、中ほど東寄りに建つ。桁行五間、梁間三間、二階建土蔵で、屋根は桟瓦葺。内部は一、二階とも一室とし、西側正面には全長に渡って一間幅の庇をかけ、南端部のみ囲って道具入れとする。近世商家の屋敷構えを構成する建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011558"},{"id":"00011562","register_sub_id":"101","register_pk":"210497","name":"三宅家住宅裏長屋門","kana":"みやけけじゅうたくうらながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県安芸郡海田町稲荷町184","lat":34.37333306,"lng":132.53294306,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋造、瓦葺、建築面積53㎡","structure_material":"木造平屋造","registered":"2017.05.02(平成29.05.02)","register_no":"034-212","desc":"敷地南端を画す長屋門。もとは瀬野川旧流路の河岸に面していた。桁行八間半、梁間一間半の東西棟の中央やや西寄りに門口を開き、その西は桁行三間、梁間二間の規模で北に延ばして厩舎とする。水陸の中継商業で栄えた海田町の歴史を今に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011562"},{"id":"00011557","register_sub_id":"101","register_pk":"210492","name":"三宅家住宅主屋","kana":"みやけけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県安芸郡海田町稲荷町184","lat":34.373801,"lng":132.533364,"geo_status":"db","era":"江戸後期／明治中期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積125㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"34-0207","desc":"旧山陽道に北面する商家。妻入のつし二階建、桟瓦葺。東側に通り土間を通し、表側からミセ、ゲンカン、ナカノマ、ザシキの一列四室を並べる。正面に奥行一間の大きな下屋庇を設け、つし二階の正面は塗籠の軸組を見せ、街道沿いの歴史的景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011557"},{"id":"00011559","register_sub_id":"101","register_pk":"210494","name":"三宅家住宅新蔵","kana":"みやけけじゅうたくしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県安芸郡海田町稲荷町184","lat":34.37356806,"lng":132.53310389,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"34-0209","desc":"敷地中ほどの西寄りに建ち、衣裳蔵と対面する。桁行三間、梁間二間、二階建で、屋根は桟瓦葺。正面中央やや北寄りの扉口を設け、一、二階とも正面のみに半間幅、鉄格子の内側に内開きの塗籠戸とする窓を開く。敷地内の土蔵の中では最も丁寧な作りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011559"},{"id":"00011561","register_sub_id":"101","register_pk":"210496","name":"三宅家住宅新米蔵","kana":"みやけけじゅうたくしんこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県安芸郡海田町稲荷町184","lat":34.37342389,"lng":132.53310694,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"34-0211","desc":"敷地中央東側、衣裳蔵の南に建ち、古米蔵と対面する。桁行三間、梁間二間と小規模な二階建で、一、二階とも一室とし、南妻面に窓二箇所を開く。正面側には全長に渡って庇を設けている。敷地南端の裏長屋門に近くにあって、小作米を貯蔵していた土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011561"},{"id":"00011560","register_sub_id":"101","register_pk":"210495","name":"三宅家住宅古米蔵","kana":"みやけけじゅうたくふるこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県安芸郡海田町稲荷町184","lat":34.37351389,"lng":132.53303889,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積43㎡","structure_material":"土蔵造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"34-0210","desc":"敷地中央西側、新蔵の南に建つ。桁行五間、梁間三間、二階建で、一階中央に扉口を開き、その両側に窓を設け、二階には窓四箇所を開く。一階開口部には板庇を設ける。敷地内では最も規模が大きい土蔵で、白壁に窓を開く外観が、敷地景観を形づくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011560"},{"id":"00004422","register_sub_id":"101","register_pk":"105412","name":"宮島町立宮島歴史民俗資料館（旧江上家住宅）蔵","kana":"みやじまちょうりつみやじまれきしみんぞくしりょうかん（きゅうえがみけじゅうたく）くら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県廿日市市宮島町57","lat":34.29515352,"lng":132.3176491,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0073","desc":"主屋東妻面に建つ。土蔵造２階建，桁行梁間とも２間半の方形で，１・２階とも主屋と続き，棟を主屋と同じ東西棟の切妻造，桟瓦葺とする。外壁は漆喰塗，１階腰を縦板で覆い，１・２階境に水切瓦を廻す。主屋との連続性を重視し，商家の表構えを構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004422"},{"id":"00004421","register_sub_id":"101","register_pk":"105411","name":"宮島町立宮島歴史民俗資料館（旧江上家住宅）主屋","kana":"みやじまちょうりつみやじまれきしみんぞくしりょうかん（きゅうえがみけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県廿日市市宮島町57","lat":34.29520517,"lng":132.31753765,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積201㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"34 － 0072","desc":"厳島神社西廻廊の西方にあり，通りに南面して建つ。桁行１３．５ｍの木造２階建，切妻造，桟瓦葺，平入で，平面は通り土間式，西妻に平屋建の茶室部を付属する。深い軒や庇を支持する持送り板，いわゆる千本格子の建具など，宮島における商家建築の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004421"},{"id":"00016604","register_sub_id":"101","register_pk":"574966","name":"村井家住宅主屋（旧市村郵便局）","kana":"むらいけじゅうたくおもや（きゅういちむらゆうびんきょく）","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県尾道市御調町市字市1198-1他","lat":34.51543472,"lng":133.14943278,"geo_status":"db","era":"江戸末期／昭和4年増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、セメント瓦葺、建築面積213㎡","structure_material":"木造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"34 - 0330","desc":"旧出雲往来に東面して建つ旧郵便局を併設する主屋。2階建切妻造桟瓦葺の町家の南側にアーチやメダリオンで飾った石造風外観の郵便局を付加する。全体の平面は奥行が深く、座敷は良材を用いた端正なつくり。洋風の郵便局を備えた外観が街道の賑わいを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016604"},{"id":"00016605","register_sub_id":"101","register_pk":"574967","name":"村井家住宅土蔵","kana":"むらいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県尾道市御調町市字市1198-1他","lat":34.51543472,"lng":133.14943278,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積64㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"34 - 0331","desc":"主屋の土間北側に接続して建つ土蔵。二階建切妻造、置屋根形式の桟瓦葺で正面に下屋を付す。奥行が深い平面を前後に分け、一階背面側は土間と和室を配し、二階は防火壁で画す。小屋組は曲がり梁を用いた和小屋。主屋と一体となって街道沿いの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016605"},{"id":"00008375","register_sub_id":"101","register_pk":"134017","name":"村上家住宅石垣","kana":"むらかみけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県福山市今津町字長波1929","lat":34.45703991,"lng":133.25006196,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石造、延長77m","structure_material":"石造","registered":"2010.09.10(平成22.09.10)","register_no":"34 － 0103","desc":"敷地の南面から西・北面かけて築かれる石垣で、高さは南西角で４．２ｍ、北西角で２．３ｍを測り、総延長７６ｍに及ぶ。打ち込み矧ぎの乱積とし、各角は算木積とする。一部に明治期の火災の痕跡を残す。城郭のような威容を誇る敷地構えをつくり上げている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008375"},{"id":"00008369","register_sub_id":"101","register_pk":"134011","name":"村上家住宅衣装蔵","kana":"むらかみけじゅうたくいしょうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県福山市今津町字長波1929","lat":34.45730068,"lng":133.2499861,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積48㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"34 － 0097","desc":"主屋の北に位置する。切石積基礎上に建つ土蔵造２階建で、桁行９．８ｍ梁間４．９ｍ、東西棟の切妻造本瓦葺とする。高く竪板を張り、軒まわりを漆喰仕上げとする。１階は二室に分け、各室に出入口を設け、庇をかける。内壁も漆喰で仕上げるなど丁寧なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008369"},{"id":"00008372","register_sub_id":"101","register_pk":"134014","name":"村上家住宅井戸屋形","kana":"むらかみけじゅうたくいどやかた","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"広島県","address":"広島県福山市今津町字長波1929","lat":34.45738883,"lng":133.25017868,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、建築面積3.8㎡、井戸付","structure_material":"木造","registered":"2010.09.10(平成22.09.10)","register_no":"34 － 0100","desc":"米蔵の東に位置する。桁行２．７ｍ梁間１．４ｍの切妻造桟瓦葺。切石上に方柱を建て、貫で固め、頂部に梁と桁を架す。一軒疎垂木。中央に井戸を設け、井戸枠は凸状の花崗岩を組み合わせる。石敷の洗い場を周囲に設ける。近世の生活空間の一端を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008372"},{"id":"00008374","register_sub_id":"101","register_pk":"134016","name":"村上家住宅腕木門","kana":"むらかみけじゅうたくうでぎもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県福山市今津町字長波1929","lat":34.45710625,"lng":133.25009759,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口3.4m、塀付","structure_material":"木造","registered":"2010.09.10(平成22.09.10)","register_no":"34 － 0102","desc":"主屋南面の庭を画する門で、左右に瓦塀を付ける。３．５ｍ間隔で本柱をたて、腕木で軒桁を支持。一軒疎垂木。切妻造桟瓦葺。本柱間を楣で固め、上に井桁の欄間を飾り、下は両脇を土壁とし、中央に引分け戸をたてる。瀟洒な意匠をもち、庭園の景観要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008374"},{"id":"00008370","register_sub_id":"101","register_pk":"134012","name":"村上家住宅米蔵","kana":"むらかみけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県福山市今津町字長波1929","lat":34.45737286,"lng":133.25012216,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"34 － 0098","desc":"衣装蔵の東方に東西棟で建つ。桁行４．７ｍ梁間４．０ｍの土蔵造２階建で、南面から東に下屋を設け、南面の一部を室内に取り込み、東は漬物小屋とする。切妻造本瓦葺、切石積基礎上に建ち、外壁は漆喰仕上げとする。桟瓦葺の下屋が外観に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008370"},{"id":"00008368","register_sub_id":"101","register_pk":"134010","name":"村上家住宅主屋","kana":"むらかみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県福山市今津町字長波1929","lat":34.4571726,"lng":133.24997965,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積152㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"34 － 0096","desc":"松永湾を南方に臨む丘陵地に占める敷地の西寄りに位置する。入母屋造桟瓦葺の木造２階建、北面に深い下屋、東面に入母屋造妻入の玄関を付設。２階は東西に二室並べ、西・南に縁をめぐらし、西室にトコ構えや欄間を飾る。良材を用い、繊細な意匠になる接客座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008368"},{"id":"00008373","register_sub_id":"101","register_pk":"134015","name":"村上家住宅長屋門","kana":"むらかみけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県福山市今津町字長波1929","lat":34.45713451,"lng":133.25023151,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"34 － 0101","desc":"主屋の東南に東西棟で建つ。入母屋造桟瓦葺で、西面から南面に下屋をまわす。桁行１６ｍ梁間３．９ｍの木造平屋建。東端を物置、西半部は居室とし、その間に間口３．７ｍの門口を開ける。門口は東半を壁とする引込み戸をたてる。風格ある屋敷正面をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008373"},{"id":"00008371","register_sub_id":"101","register_pk":"134013","name":"村上家住宅納屋","kana":"むらかみけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県福山市今津町字長波1929","lat":34.45735443,"lng":133.25008899,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"34 － 0099","desc":"衣装蔵と米蔵を繋ぐ両下造。桁行５．０ｍ梁間４．９ｍの木造平屋建。内部にトコや戸棚を残すなど、寺子屋に使用された名残を留める。敷地内側を桟瓦葺で真壁とするのに対して、北外側を本瓦葺、大壁造として、米蔵や衣装蔵と一体で趣のある屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008371"},{"id":"00015382","register_sub_id":"101","register_pk":"532506","name":"山中家住宅土蔵","kana":"やまなかけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県廿日市市宮島町字中之町524","lat":34.29870833,"lng":132.32205833,"geo_status":"db","era":"明治2年／平成16年改修","year":1869,"year_source":"db","year_min":1869,"year_max":1869,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積61㎡","structure_material":"土蔵造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"34 - 0321","desc":"宮島の東町にある旧呉服商の家財蔵。二階建切妻造妻入桟瓦葺で外壁漆喰塗仕上、腰は竪板張。南面戸口に庇を付し、掛子塗の両開戸を吊る。一階は土間、二階は板敷で中央に独立柱を立て、小屋組は登梁形式。正面に家紋を付し、呉服商の繁栄を伝える重厚な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015382"},{"id":"00000265","register_sub_id":"101","register_pk":"101255","name":"吉原家住宅表長屋門","kana":"よしはらけじゅうたくおもてながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県尾道市向島町3854","lat":34.3875627,"lng":133.20722619,"geo_status":"db","era":"明治18","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積114㎡","structure_material":"木造平屋建","registered":"1997.07.15(平成9.07.15)","register_no":"34 － 0009","desc":"広大な屋敷構えをもつ農家の長屋門形式の表門。明治期の建築であるが，文政８年(1825)の家相図により，その時にあった門の規模・形式を継承したものと推定される。向島では類例が少ない長大な規模をもつ表門で，普請関係の記録も残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000265"},{"id":"00006707","register_sub_id":"101","register_pk":"107690","name":"岩国徴古館第二収蔵庫","kana":"いわくにちょうこかんだいにしゅうぞうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県岩国市横山2-7-19","lat":34.170937,"lng":132.17717,"geo_status":"db","era":"明治24","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造2階建、瓦葺、建築面積95㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"35 － 0059","desc":"第一収蔵庫の東方に建つ。旧岩国藩主吉川家住宅の土蔵として建設。桁行６間梁間３間規模、切妻造桟瓦葺の２階建土蔵で、石積の基礎上に建ち、南面に桁行５間梁間１間半の下屋を設けて蔵前とし、蔵前も含め軒裏や螻羽まで塗り込め、落ち着きのある外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006707"},{"id":"00004820","register_sub_id":"101","register_pk":"105810","name":"歌野清流庵","kana":"うたのせいりゅうあん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"山口県","address":"山口県下関市菊川町大字上岡枝字郷ケ原1812","lat":34.16763509,"lng":131.02108225,"geo_status":"db","era":"江戸末期／明治期増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺、建築面積161㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"35 － 0046","desc":"江戸中期から楮栽培の入植地となった歌野地区の谷あいに位置する農家。桁行６間半梁行５間規模，東西棟の寄棟造，茅葺で，西側を土間，北側床上部を四間取とし，東北部に４畳半座敷などを増築する。ダム建設により離村した楮栽培集落農家の面影を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004820"},{"id":"00016610","register_sub_id":"101","register_pk":"574972","name":"岡藤家住宅御成門及び塀","kana":"おかふじけじゅうたくおなりもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"山口県","address":"山口県長門市三隅中字中市1910","lat":34.34459889,"lng":131.26245583,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"御成門 木造、瓦葺、間口2.0m、脇門付 塀 土塀、瓦葺、総延長43m","structure_material":"御成門 木造","registered":"2026.02.10(令和8.02.10)","register_no":"35 - 0142","desc":"主屋の東側に建つ御成門と敷地東辺を区画する塀。御成門は通りからやや引き込み建つ一間腕木門桟瓦葺で両開板扉を建て、東側に脇門を備える。塀は桟瓦葺の土塀で総延長43メートル、東西方向に一段低く延びて門に取り付く。旧家の屋敷構えを整える門及び塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016610"},{"id":"00016606","register_sub_id":"101","register_pk":"574968","name":"岡藤家住宅主屋","kana":"おかふじけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山口県","address":"山口県長門市三隅中字中市1910","lat":34.34459889,"lng":131.26245583,"geo_status":"db","era":"江戸中期／寛政10年（1798）頃増築、昭和62年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積297㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"35 - 0138","desc":"赤間ケ関街道に北面して建つ造酒屋の主屋。平屋建入母屋造桟瓦葺。正面に下屋を付し、西寄りに戸口、東に出格子を構える。内部は西を通り土間とし、東に二列六室を並べ、南東に座敷を張り出す。建ちが低く、間口長大な町家で、地域の歴史的な景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016606"},{"id":"00016608","register_sub_id":"101","register_pk":"574970","name":"岡藤家住宅茶室","kana":"おかふじけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和中","pref":"山口県","address":"山口県長門市三隅中字中市1910","lat":34.34459889,"lng":131.26245583,"geo_status":"db","era":"昭和30年頃","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"35 - 0140","desc":"主屋の南方に建つ茶室。北は切妻造、南は入母屋造で全体桟瓦葺とし、北に銅板葺下屋を付し、東に腰掛待合を配す。中廊下を挟み南に四畳半茶室、北に三畳間を並べ、北面に濡縁、南東に水屋を付す。茶室は西面に床を構え掛込天井とする。中庭の点景を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016608"},{"id":"00016609","register_sub_id":"101","register_pk":"574971","name":"岡藤家住宅土蔵","kana":"おかふじけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県長門市三隅中字中市1910","lat":34.34459889,"lng":131.26245583,"geo_status":"db","era":"明治21年頃","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積48㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"35 - 0141","desc":"敷地南側、茶室西隣に建つ調度品の収蔵蔵。二階建切妻造桟瓦葺で、外壁漆喰塗仕上で水切瓦を一段付け、腰に縦長に目地を切る。北に戸口を設け瓦庇を付す。各階一室の板敷で小屋組は大梁に束を立て棟木と母屋桁を受ける。敷地南側の景観を形成する重厚な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016609"},{"id":"00016607","register_sub_id":"101","register_pk":"574969","name":"岡藤家住宅離れ","kana":"おかふじけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県長門市三隅中字中市1910","lat":34.34459889,"lng":131.26245583,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"35 - 0139","desc":"主屋の南方に建つ離れ。平屋建切妻造桟瓦葺、外壁下見板張とする。内部は洋室の北・西面に廊下を廻し、北東隅から主屋に繋がる。洋室は南面に出窓、東面に引違窓を開き、床は板張、壁と天井は白漆喰仕上で、天井に中心飾を付す。簡素ながら明るく瀟洒な洋室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016607"},{"id":"00016730","register_sub_id":"101","register_pk":"579214","name":"木梨家住宅一ノ蔵","kana":"きなしけじゅうたくいちのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県山口市桜畠六丁目2800他","lat":34.202218,"lng":131.495992,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"35 - 0146","desc":"敷地西辺中ほどに建つ、男爵木梨精一郎の遺品収蔵庫。木造平屋建、切妻造南北棟、桟瓦葺で、東面に出入口を開く。外壁は内法より下は竪羽目板張、上部は漆喰塗仕上とする。内部は一室で、壁は竪羽目板張、床は板張とする。敷地西面の屋敷構えを形成する蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016730"},{"id":"00016732","register_sub_id":"101","register_pk":"579216","name":"木梨家住宅表門","kana":"きなしけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県山口市桜畠六丁目2800他","lat":34.20207,"lng":131.496074,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、銅板葺、間口2.9m","structure_material":"木造","registered":"2026.07.09(令和8.07.09)","register_no":"35 - 0148","desc":"木梨堤を横断する土橋の正面、敷地西辺南寄りに西面して建つ一間薬医門。切妻造銅板葺で、両脇に潜戸を設ける。本柱間に渡した冠木に女梁・男梁を組み、束上の大斗肘木で棟木を受け、軒は一軒疎垂木。門口に板戸を吊る。質実な意匠で屋敷の表構えをつくる門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016732"},{"id":"00016727","register_sub_id":"101","register_pk":"579211","name":"木梨家住宅主屋","kana":"きなしけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県山口市桜畠六丁目2800他","lat":34.202167,"lng":131.496307,"geo_status":"db","era":"慶応3年（1867）／明治中期増築、昭和40年代改修","year":1867,"year_source":"db","year_min":1867,"year_max":1867,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積190㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"35 - 0143","desc":"木梨堤と呼ばれる池に臨む武家の隠居屋敷の主屋。敷地東側の山裾に建つ片入母屋造桟瓦葺で、北側に落棟を延ばし、西面に入母屋造の式台玄関を付す。内部は南端に二間続きの座敷を配して床を構え、南庭に開けた内縁を通す。武家の構えを留める格調高い主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016727"},{"id":"00016729","register_sub_id":"101","register_pk":"579213","name":"木梨家住宅二階屋","kana":"きなしけじゅうたくにかいや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県山口市桜畠六丁目2800他","lat":34.202073,"lng":131.496197,"geo_status":"db","era":"大正後期／平成3年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建一部平屋建、瓦葺、建築面積86㎡","structure_material":"木造2階建一部平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"35 - 0145","desc":"敷地南西隅に建つ離れ。二階建寄棟造の西面に、西面入母屋造の平屋建が付き、全体桟瓦葺とする。外壁は下見板張で矩形の窓を並べて洋風を加味。北面に玄関を開き、内部一・二階とも座敷を配して、南側に内縁を通す。木梨堤越しに望む屋敷構えの中核をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016729"},{"id":"00016731","register_sub_id":"101","register_pk":"579215","name":"木梨家住宅二ノ蔵","kana":"きなしけじゅうたくにのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和後","pref":"山口県","address":"山口県山口市桜畠六丁目2800他","lat":34.202264,"lng":131.496125,"geo_status":"db","era":"明治28年","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造2階建、瓦葺、建築面積23㎡","structure_material":"木造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"35 - 0147","desc":"主屋の北西に位置する家財蔵。木造二階建、切妻造南北棟、桟瓦葺で、西面に出入口を開く。小屋組は登梁を地棟で受ける。外壁は大壁で竪羽目板張、内部は一・二階とも一室で、壁は竪羽目板張、床は板張とする。表門から主屋に至る敷地南側の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016731"},{"id":"00016728","register_sub_id":"101","register_pk":"579212","name":"木梨家住宅離れ","kana":"きなしけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県山口市桜畠六丁目2800他","lat":34.202082,"lng":131.496442,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積43㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"35 - 0144","desc":"主屋の南東に位置する離れ座敷。入母屋造桟瓦葺で八畳の座敷と四畳間を並べ、南・西面に濡縁を廻らす。縁外に八角形の柱を立て、杉の磨丸太の軒桁を受ける。座敷は床の両脇を床脇とし平書院を備える。中庭越しに木梨堤を望む数寄屋風の軽やかな意匠の座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016728"},{"id":"00001367","register_sub_id":"101","register_pk":"102357","name":"旧礒乃屋釜屋","kana":"きゅういそのやかまや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県光市室積五丁目262-2","lat":33.92583569,"lng":131.970825,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積32㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"35 － 0029","desc":"主屋下屋の南東端から南側小路に沿って浜側にのびる瓦葺切妻屋根の便益棟部分で，主屋下屋よりさらに棟を落とす。井戸上屋を兼ねた棟で，井戸の脇に煉瓦造の流し場と竃を設ける。屋敷構えの発展過程を理解するうえで必要な構成要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001367"},{"id":"00001365","register_sub_id":"101","register_pk":"102355","name":"旧礒乃屋主屋","kana":"きゅういそのやしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県光市室積五丁目262-2","lat":33.92594431,"lng":131.97069507,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積185㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"35 － 0027","desc":"室積湾を背にし，表通りに西面して建つ。木造２階建，本瓦葺寄棟屋根の妻入で，軒裏と外壁を白漆喰で塗込め，正面と両側面に下屋を付け，２階中央と玄関両側の格子窓により端正な表構えを造る。材木問屋を営んだ旧家で，木太い架構にも見所がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001365"},{"id":"00001366","register_sub_id":"101","register_pk":"102356","name":"旧礒乃屋離れ座敷（茶室）","kana":"きゅういそのやはなれざしき（ちゃしつ）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県光市室積五丁目262-2","lat":33.9258911,"lng":131.97086459,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積44㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"35 － 0028","desc":"明治後期に主屋北側に増築された角座敷から浜側にのびた渡り廊下で繋がれる。瓦葺入母屋屋根の三方に庇を回した構成をとり，４畳半の茶室を中心に，北側に３畳間と便所を設ける。上質で端正な造りの離れ座敷で，主屋との間に程良い中庭的空間をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001366"},{"id":"00006705","register_sub_id":"101","register_pk":"107688","name":"旧宇野千代家住宅主屋","kana":"きゅううのちよけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県岩国市川西2-9-35","lat":34.15715004,"lng":132.17497776,"geo_status":"db","era":"明治初期／明治中期増改築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積121㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"35 － 0057","desc":"旧山陽道脇道に西面して建つ。桁行３間半梁行３間規模、切妻造桟瓦葺、平入の木造つし２階建で、南方をもと土間、北方を６畳２室の床上部とし、北面と東背面は増築され、南側には台所や座敷、浴室等からなる付属屋が繋がる。出格子や出桁など町家の意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006705"},{"id":"00004484","register_sub_id":"101","register_pk":"105474","name":"旧吉川邸厩門","kana":"きゅうきっかわていうまやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県岩国市横山2-7","lat":34.17156852,"lng":132.17737442,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積148㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"35 － 0045","desc":"吉川経健が建設した邸宅の長屋門。桁行３０ｍと長大で，西を正面とし，石積基壇上に建つ。南寄りに門口を構え，外壁漆喰塗とし，要所に横連子窓を設ける。屋根は寄棟造，桟瓦葺。小屋組は一部に変形トラス組を用いる。近代の大邸宅の様子を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004484"},{"id":"00001295","register_sub_id":"101","register_pk":"102285","name":"旧野村家住宅土蔵","kana":"きゅうのむらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県山口市大字下竪小路12","lat":34.18370017,"lng":131.47839472,"geo_status":"db","era":"明治19頃","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"土蔵造平屋建，瓦葺，建築面積31㎡","structure_material":"土蔵造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"35 － 0026","desc":"酒造業で栄えた家の繁栄を示す附属施設のひとつ。主屋の東北方，旧萩往還道（萩から山口を経て三田尻に至る）に面した広い屋敷地のほぼ中央に建つ。桁行３間，梁間２間の置屋根形式の蔵で，家財道具を納めるなど内向き用に使われていた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001295"},{"id":"00014208","register_sub_id":"101","register_pk":"508838","name":"旧福元家住宅石塀及び煉瓦塀","kana":"きゅうふくもとけじゅうたくいしべいおよびれんがべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県大島郡周防大島町大字西屋代字下里2144","lat":33.92153333,"lng":132.20031111,"geo_status":"db","era":"大正15年頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"石造及び煉瓦造、延長45m、門柱付","structure_material":"石造及び煉瓦造","registered":"2022.02.17(令和4.02.17)","register_no":"35-0110","desc":"アメリカ移民で財を成した貿易商の屋敷北外郭に廻らす塀。旧接続道側を石塀、裏側となる北西を鉱滓煉瓦塀とする。石塀は江戸切りの石をはめて笠石を載せ、煉瓦塀は長手積で笠石は小口積にモルタルを盛る。門柱は柱頭頸切り角柱に木瓜形を彫り意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014208"},{"id":"00014209","register_sub_id":"101","register_pk":"508839","name":"旧福元家住宅井戸及び給水塔","kana":"きゅうふくもとけじゅうたくいどおよびきゅうすいとう","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山口県","address":"山口県大島郡周防大島町大字西屋代字下里2144","lat":33.92132778,"lng":132.20038333,"geo_status":"db","era":"大正15年頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"煉瓦造、高さ2.8m、面積0.9㎡","structure_material":"煉瓦造","registered":"2022.02.17(令和4.02.17)","register_no":"35-0111","desc":"アメリカ移民で財を成した貿易商の屋敷内水道のための井戸と給水塔。主屋南東側に位置し、煉瓦造モルタル仕上の給水塔を花崗岩石組井戸の上部に載せる。平面一メートル四方、高さ二・八メートル、井戸水を貯めたタンクの水量計や給水するパイプ等の痕が残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014209"},{"id":"00014206","register_sub_id":"101","register_pk":"508836","name":"旧福元家住宅主屋","kana":"きゅうふくもとけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県大島郡周防大島町大字西屋代字下里2144","lat":33.92138611,"lng":132.20028333,"geo_status":"db","era":"大正15年／平成10年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積294㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"35-0108","desc":"アメリカ移民で財を成した貿易商が郷里の屋代地区に建てた近代和風邸宅。入母屋造桟瓦葺、二階建南北棟を中心に中庭を囲んで角座敷を延ばす。全体を和風意匠とする一方で、板敷の台所にアメリカから持ち帰ったオーブンや水廻り設備を置き、水道も整備する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014206"},{"id":"00014207","register_sub_id":"101","register_pk":"508837","name":"旧福元家住宅土蔵","kana":"きゅうふくもとけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県大島郡周防大島町大字西屋代字下里2144","lat":33.92148333,"lng":132.20035278,"geo_status":"db","era":"大正15年／平成10年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"35-0109","desc":"アメリカ移民で財を成した貿易商の道具蔵で主屋北に接続する。土蔵造二階建、入母屋造桟瓦葺、軒は漆喰仕上で壁を竪板張。戸口は敷地北辺石段側と主屋一・二階の三箇所で利便性を高める。集落を見渡す北面は窓を並べ、繰形付持送りで出桁とし、意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014207"},{"id":"00010062","register_sub_id":"101","register_pk":"196209","name":"山水園本館","kana":"さんすいえんほんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山口県","address":"山口県山口市緑町1061他","lat":34.17092042,"lng":131.46245617,"geo_status":"db","era":"大正前期／昭和初期・昭和25・昭和38改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階一部3階建、瓦葺、建築面積1340㎡","structure_material":"木造2階一部3階建","registered":"2014.04.25(平成26.04.25)","register_no":"35 － 0086","desc":"湯田温泉街の東方に位置する温泉旅館で、大正期の別荘建築に、数次に増改築が加えられた複合建物。大正期の行在閣棟は庭園と一体的な構成の上質な近代和風建築で、のちの増築部も材工ともに優れた数寄屋意匠になり、各時代の異なる趣向が良好に調和する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010062"},{"id":"00001954","register_sub_id":"101","register_pk":"102944","name":"四熊家住宅主屋","kana":"しくまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山口県","address":"山口県周南市土井1-1-1","lat":34.08009613,"lng":131.77292917,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、茅一部瓦葺、建築面積237㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"35 － 0036","desc":"江戸時代初期から医業を受け継いだ旧家の主屋。桁行８間半，梁間５間半，２階建で，屋根は寄棟造，茅葺で，周囲に桟瓦葺の庇を巡らす。県下でも数少ない大規模な茅葺屋根を残す民家で，裏山を背負って建つ姿は，地域を代表する歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001954"},{"id":"00010513","register_sub_id":"101","register_pk":"199454","name":"清水家住宅主屋","kana":"しみずけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山口県","address":"山口県防府市大字富海字東町2657","lat":34.050426,"lng":131.646655,"geo_status":"db","era":"明治11／昭和50代改修","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積269㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"35 － 0093","desc":"旧山陽道富海宿の角地に北面して建つ。つし二階建桟瓦葺の町家で、通り土間と六間取の床上部、東へ張出す角座敷、背面に附属する台所と隠居部屋からなる。正面に下屋を設け、漆喰塗込めの二階軒を繰形付の持送で支える。宿場町の景観を伝える上で重要な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010513"},{"id":"00012650","register_sub_id":"101","register_pk":"367944","name":"白石家住宅呉服蔵","kana":"しらいしけじゅうたくごふくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県防府市宮市町311他","lat":34.061096,"lng":131.570877,"geo_status":"geocoded","era":"明治21年／平成27年改修","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積49㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"35 － 0100","desc":"主屋後方西寄りに南北棟で建つ。土蔵造二階建、切妻造桟瓦葺で、外壁漆喰塗で鉢巻と水切を廻し、東面北寄りに戸口を設けて下屋を付す。小屋は八角断面の梁に角材の梁を重ね、桁を受ける独特な形式の和小屋を組む。呉服商の営みの一端を伝える附属建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012650"},{"id":"00012649","register_sub_id":"101","register_pk":"367943","name":"白石家住宅主屋","kana":"しらいしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県防府市宮市町311他","lat":34.061096,"lng":131.570877,"geo_status":"geocoded","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積274㎡","structure_material":"木造2階一部平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"35 － 0099","desc":"市中心部の商家。主屋は敷地中央に建ち、入母屋造総二階建の主体部は、茶室や座敷を網代天井や霞棚風棚など自由な造形の数寄屋意匠とする。南に張出す寄棟造は12畳半の大座敷に大ぶりの座敷飾を備える。京大工による和風意匠の濃淡を巧みに使い分けた優品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012649"},{"id":"00012651","register_sub_id":"101","register_pk":"367945","name":"白石家住宅道具蔵及び食物蔵","kana":"しらいしけじゅうたくどうぐぐらおよびしょくもつぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県防府市宮市町311他","lat":34.061096,"lng":131.570877,"geo_status":"geocoded","era":"明治21年頃","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"土蔵造平屋一部2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造平屋一部2階建","registered":"2018.11.02(平成30.11.02)","register_no":"35 － 0101","desc":"主屋前方東寄りに南北棟で建つ。土蔵造平屋建、切妻造桟瓦葺、外壁漆喰塗で鉢巻と直下の帯一筋を廻す。内部を南北に二分して南を食物蔵、北を道具蔵とし、西北二面に出入口を設けて、繰形を施した持送付の庇を付す。老舗の格式ある屋敷構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012651"},{"id":"00001535","register_sub_id":"101","register_pk":"102525","name":"水西書院","kana":"すいせいしょいん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県岩国市川西4-2-4","lat":34.15847007,"lng":132.180023,"geo_status":"db","era":"明治19","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造2階建、瓦葺、建築面積305㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"35 － 0035","desc":"旧岩国藩主吉川家の仮住居として建てられ，吉川家の接客所として利用されたことで知られる。木造２階建，寄棟造，桟瓦葺で，茶室を付設する。階下は１５畳の座敷２室と畳縁，階上は３０畳の大広間と板縁から構成され，城山と錦帯橋を借景とする造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001535"},{"id":"00005975","register_sub_id":"101","register_pk":"106960","name":"中野家住宅石垣","kana":"なかのけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"山口県","address":"山口県下関市大字内日上2777","lat":34.09669125,"lng":130.955802,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石造、総延長58m","structure_material":"石造","registered":"2006.11.29(平成18.11.29)","register_no":"35 － 0054","desc":"敷地の東辺及び東辺北寄りの進入路の両側を形成する石垣で，北側を１８ｍ，南側を４０ｍとする。打込み矧ぎの乱積で，高さは約３ｍ。東辺北側の中央付近に目地が切れ，時期差が認められる。出隅部の曲線を丁寧につくり，敷地の格式ある外観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005975"},{"id":"00006061","register_sub_id":"101","register_pk":"107046","name":"中野家住宅主屋","kana":"なかのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"山口県","address":"山口県下関市大字内日上2777","lat":34.09682782,"lng":130.95562034,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積170㎡、井戸付","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"35 － 0050","desc":"狩音山の東麓に敷地を構える農家住宅。敷地中央西寄りに東面して建つ。寄棟造，茅葺（鉄板仮葺）で四周に瓦葺庇を巡らす。北側に土間を設けた整形六間取で，東に縁を設ける。南東８畳座敷に床と仏壇を付ける。改造が少なく，山村の佇まいを伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006061"},{"id":"00006063","register_sub_id":"101","register_pk":"107048","name":"中野家住宅土蔵","kana":"なかのけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県下関市大字内日上2777","lat":34.0967177,"lng":130.95571207,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"35 － 0052","desc":"主屋の南東に建つ南北棟の土蔵造２階建。桁行３間，梁間２間規模の切妻造，桟瓦葺で，北面に瓦葺庇を付け，塗戸と板戸を片引きに建込む。南面２階に窓を開く。外壁は漆喰塗に，鉄板仮張としている。小屋組は与次郎組。敷地遠景のアクセントとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006063"},{"id":"00006062","register_sub_id":"101","register_pk":"107047","name":"中野家住宅納屋","kana":"なかのけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"山口県","address":"山口県下関市大字内日上2777","lat":34.09695911,"lng":130.9556387,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積111㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"35 － 0051","desc":"主屋の北に建つ木造平屋建で，桁行９間，梁間３間，東西棟の寄棟造，茅葺（鉄板仮葺）である。中央４間半がもと牛小屋で，西に建具無しの物入，東に板床の物置を設ける。牛小屋の北東部は低い土塀で囲う。せがい造に渦付の持送りを付けるなど，つくりは丁寧。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006062"},{"id":"00005972","register_sub_id":"101","register_pk":"106957","name":"中野家住宅塀","kana":"なかのけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県下関市大字内日上2777","lat":34.09681893,"lng":130.95575119,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土塀、瓦葺、延長8.3m","structure_material":"土塀","registered":"2006.11.29(平成18.11.29)","register_no":"35 － 0053","desc":"主屋の東辺中央から東に延びる土塀。主屋入口の前庭と南の庭園を区画する。延長８．３ｍで，西寄りに１．８ｍの通り口を開く。基底幅５３ｃｍの切込み矧ぎの石積基礎とし，上部は瓦葺で，総高１．４ｍ。重厚なつくりとし，敷地正面の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005972"},{"id":"00005920","register_sub_id":"101","register_pk":"106905","name":"藤原義江記念館（旧リンガー邸）","kana":"ふじわらよしえきねんかん（きゅうりんがーてい）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山口県","address":"山口県下関市阿弥陀寺町3-14","lat":33.959126,"lng":130.946594,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造地上3階地下1階建、建築面積133㎡","structure_material":"鉄筋コンクリート造地上3階地下1階建","registered":"2006.10.18(平成18.10.18)","register_no":"35 － 0048","desc":"関門海峡を望む紅石山の中腹に建つ，鉄筋コンクリート造地上３階地下１階の住宅建築である。平滑な壁面に小庇付の矩形窓を開き，装飾要素を排除している。内部諸室も直線を基調とした意匠でまとめられている。近代建築運動の展開の一端を示す遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005920"},{"id":"00015243","register_sub_id":"101","register_pk":"530667","name":"船越家住宅主屋","kana":"ふなこしけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県山口市後河原字吉田45","lat":34.18541111,"lng":131.47592222,"geo_status":"db","era":"昭和4年／昭和7年増築","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積122㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0120","desc":"一の坂川に面した敷地に東京牛込から移築した住宅。木造二階建、片半切妻造、桟瓦葺の東西棟で南面に玄関を付し、西端に洋館の応接間を付す。各階二室続きの座敷を配し、東と南面に廊下を廻す。二階座敷は床と床脇を組合せた自由な構成とした近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015243"},{"id":"00010065","register_sub_id":"101","register_pk":"196212","name":"山内家住宅男衆部屋","kana":"やまのうちけじゅうたくおとこしゅべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山口県","address":"山口県防府市栄町2-1223-1","lat":34.05820372,"lng":131.57126499,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"35 － 0089","desc":"敷地の東側北寄りに位置する、桁行五間梁間一間半、切妻造桟瓦葺の長屋。男性使用人の住まいとして利用された。西面中央に踏込み土間を設け、南に三畳及び四畳半を並べ、北は板間とする。東面外部に庇付の窓を三箇所並べ、屋敷東面の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010065"},{"id":"00010066","register_sub_id":"101","register_pk":"196213","name":"山内家住宅女衆部屋","kana":"やまのうちけじゅうたくおんなしゅべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山口県","address":"山口県防府市栄町2-1223-1","lat":34.05828327,"lng":131.57115797,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"35 － 0090","desc":"敷地の北側に位置する、桁行三間梁間一間半、切妻造桟瓦葺の長屋。女性使用人の住まいとして利用された。外観は竪板張とし、四畳半の部屋を二室並べ、南側を上がり口とする。天井は棹縁天井とするが北半と南半で棹縁の方向を変える。邸宅内の付帯施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010066"},{"id":"00010064","register_sub_id":"101","register_pk":"196211","name":"山内家住宅蔵","kana":"やまのうちけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県防府市栄町2-1222-1","lat":34.05821381,"lng":131.57098518,"geo_status":"db","era":"昭和6頃／昭和中期改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"35 － 0088","desc":"敷地の北西隅に位置する。土蔵造二階建、切妻造桟瓦葺で、壁は漆喰塗で鉢巻を廻らし、腰を竪板張とする。一階南面に戸口を開き、下屋を設ける。一階北に階段を設け、二階北面の二箇所の窓には銅板張の片開戸を開き、小庇を付す。屋敷正面の景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010064"},{"id":"00010063","register_sub_id":"101","register_pk":"196210","name":"山内家住宅主屋","kana":"やまのうちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県防府市栄町2-1222-1他","lat":34.05811526,"lng":131.57112574,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積279㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"35 － 0087","desc":"敷地中央に北面する。座敷棟と生活棟をＴ字形に連結させた配置で、屋根は入母屋造で庇を廻し、桟瓦葺とする。玄関は懸魚、舟肘木で風格を表し、座敷の欄間には花丸紋などの透彫を施す。座敷棟北西には洋間の執務室を附属する。端正にまとめた昭和初期の邸宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010063"},{"id":"00010067","register_sub_id":"101","register_pk":"196214","name":"山内家住宅納屋","kana":"やまのうちけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県防府市栄町2-1223-1","lat":34.05830529,"lng":131.57122335,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積7.6㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"35 － 0091","desc":"敷地の北側東寄り、女衆部屋に接続する、桁行四間半梁間半間、切妻造の物置。東一間を外便所とし、他は幅一間、奥行半間の物置として、南側の引違戸から使用する。外部は竪板張とし、女衆部屋とともに北面の敷地境界の塀を兼ねる。屋敷を囲む景観要素の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010067"},{"id":"00010068","register_sub_id":"101","register_pk":"196215","name":"山内家住宅門及び塀","kana":"やまのうちけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県防府市栄町2-1222-1他","lat":34.05833039,"lng":131.57088827,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"門 木造、瓦葺、間口2.1m、袖壁付 塀 煉瓦造、総延長48m","structure_material":"門 木造","registered":"2014.04.25(平成26.04.25)","register_no":"35 － 0092","desc":"敷地北面西寄りの門と、敷地を囲む塀。棟門形式の門は控柱及び袖壁付で、板戸引違とする。塀は桃色煉瓦と呼ばれる炭滓煉瓦による煉瓦塀で、半枚厚長手積とし、内側に柱形を付け、北面頂部には鋸歯状の装飾を施す。表構えを整える門と塀で、地方的特色を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010068"},{"id":"00000907","register_sub_id":"101","register_pk":"101897","name":"青木家住宅主屋","kana":"あおきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県美馬市美馬町字宮前225","lat":34.04633504,"lng":134.00481628,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建，瓦葺，建築面積149㎡","structure_material":"木造2階建","registered":"1998.10.09(平成10.10.09)","register_no":"36 － 0010","desc":"もと藍の生産を行った農家で，近代に入り建設業を営み栄えた。主屋は広大な屋敷地のほぼ中央に建つ。入母屋造の大屋根の四方に庇を付けた堂々とした外観や，鼠漆喰仕上げの壁，２階窓の意匠等に特徴がある。近代の農村部における住宅建築の変容を示す好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000907"},{"id":"00000910","register_sub_id":"101","register_pk":"101900","name":"青木家住宅倉庫","kana":"あおきけじゅうたくそうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県美馬市美馬町字宮前225","lat":34.0462701,"lng":134.00437715,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造２階建，瓦葺，建築面積104㎡","structure_material":"木造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"36 － 0013","desc":"主屋の西方，土蔵(２)の南に接続して建つ使用人の住まいを兼ねた倉庫。高さを低く押さえた長大な建物で，屋敷地の西側を区切る役割を果たしている。西面と南面は下見板貼り，東面は真壁で，土蔵と意匠をかえ，屋敷構えの景観に変化をもたせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000910"},{"id":"00000908","register_sub_id":"101","register_pk":"101898","name":"青木家住宅土蔵（１）","kana":"あおきけじゅうたくどぞう（いち）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県美馬市美馬町字宮前225","lat":34.04644637,"lng":134.00455961,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積30㎡","structure_material":"土蔵造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"36 － 0011","desc":"藍の生産に使用した蔵で，主屋の北西，道路に面して土蔵(２)に接続して建つ。比較的にせいの低い２階建の蔵で，北面と東面を漆喰で塗り込め，南面は真壁とする。北面は腰から下をなまこ壁とし，道路側の意匠を整え，屋敷構えの主要な構成要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000908"},{"id":"00000909","register_sub_id":"101","register_pk":"101899","name":"青木家住宅土蔵（２）","kana":"あおきけじゅうたくどぞう（に）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県美馬市美馬町字宮前225","lat":34.04640926,"lng":134.00435551,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積50㎡","structure_material":"土蔵造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"36 － 0012","desc":"藍の生産に使用した蔵で，屋敷地の北西隅に建つ。Ｌ字形の平面を持ち，外観上は南北棟の蔵の北端東側に東西棟の蔵が取り付いた形になる。北側と西側では腰になまこ壁を貼り，道路側の意匠を土蔵(１)とあわせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000909"}];
